<script>
// Entferne leere Parameter vor Form-Submit
document.addEventListener('DOMContentLoaded', function() {
    const form = document.getElementById('galerieFilterForm');
    if (form) {
        form.addEventListener('submit', function() {
            // Finde alle Inputs mit leerem Wert
            const inputs = form.querySelectorAll('input, select');
            inputs.forEach(input => {
                // Entferne unchecked checkboxes
                if (input.type === 'checkbox' && !input.checked) {
                    input.removeAttribute('name');
                }
                // Entferne leere Text-Inputs und Selects
                else if (input.type !== 'checkbox' && 
                         input.type !== 'hidden' && 
                         input.type !== 'submit' &&
                         input.value === '') {
                    input.removeAttribute('name');
                }
            });
        });
    }
});

// Mobile Filter Toggle Funktion
function toggleMobileFilters() {
    const container = document.querySelector('.topbar-filters-container');
    const button = document.querySelector('.mobile-filter-toggle');
    
    if (container && button) {
        container.classList.toggle('active');
        button.classList.toggle('active');
    }
}

// Custom Multiselect Dropdown Funktionalität
document.addEventListener('DOMContentLoaded', function() {
    const multiselects = document.querySelectorAll('.custom-multiselect');
    
    multiselects.forEach(container => {
        const trigger = container.querySelector('.multiselect-trigger');
        const checkboxes = container.querySelectorAll('input[type="checkbox"]');
        const label = container.querySelector('.multiselect-label');
        
        // Toggle Dropdown beim Klick auf Trigger
        trigger.addEventListener('click', function(e) {
            e.stopPropagation();
            
            // Schließe alle anderen Dropdowns
            multiselects.forEach(ms => {
                if (ms !== container) {
                    ms.setAttribute('data-open', 'false');
                }
            });
            
            // Toggle aktuelles Dropdown
            const isOpen = container.getAttribute('data-open') === 'true';
            container.setAttribute('data-open', isOpen ? 'false' : 'true');
        });
        
        // Update Label wenn Checkbox geändert wird
        checkboxes.forEach(checkbox => {
            checkbox.addEventListener('change', function() {
                updateLabel(container);
            });
        });
        
        // Verhindere dass Dropdown sich schließt beim Klicken auf Optionen
        const dropdown = container.querySelector('.multiselect-dropdown');
        dropdown.addEventListener('click', function(e) {
            e.stopPropagation();
        });
    });
    
    // Schließe alle Dropdowns wenn außerhalb geklickt wird
    document.addEventListener('click', function() {
        multiselects.forEach(ms => ms.setAttribute('data-open', 'false'));
    });
    
    // Update Label Function
    function updateLabel(container) {
        const checkboxes = container.querySelectorAll('input[type="checkbox"]:checked');
        const label = container.querySelector('.multiselect-label');
        const name = container.getAttribute('data-name');
        
        if (checkboxes.length === 0) {
            label.textContent = name === 'player' ? 'Alle Spieler' : 'Alle Teams';
        } else {
            label.textContent = checkboxes.length + ' ausgewählt';
        }
    }
});

function resetTopbarFilters() {
    const form = document.getElementById('galerieFilterForm');
    form.querySelector('input[name="search"]').value = '';
    
    // Uncheck alle Checkboxen
    form.querySelectorAll('input[type="checkbox"]').forEach(cb => {
        cb.checked = false;
    });
    
    // Update Labels
    document.querySelectorAll('.custom-multiselect').forEach(ms => {
        const label = ms.querySelector('.multiselect-label');
        const name = ms.getAttribute('data-name');
        label.textContent = name === 'player' ? 'Alle Spieler' : 'Alle Teams';
    });
    
    form.querySelector('select[name="rating"]').value = '';
    form.querySelector('select[name="sort"]').value = 'newest';
    
    // Zeitbereich zurücksetzen
    const timeFrom = form.querySelector('input[name="time_from"]');
    const timeTo = form.querySelector('input[name="time_to"]');
    if (timeFrom) timeFrom.value = '';
    if (timeTo) timeTo.value = '';
    
    form.submit();
}

function clearTimeRange() {
    const form = document.getElementById('galerieFilterForm');
    const timeFrom = form.querySelector('input[name="time_from"]');
    const timeTo = form.querySelector('input[name="time_to"]');
    if (timeFrom) timeFrom.value = '';
    if (timeTo) timeTo.value = '';
    form.submit();
}
</script>
        
