                            <circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/>
                            <path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/>
                        </svg>
                        <span id="detailCartBtnText">Warenkorb</span>
                    </button>
                </div>
                
            </div>
        </div>
    </div>
</div>

<script>
// ========================================================================
// DETAIL MODAL v1.0
// ========================================================================

window._detailCurrentIndex = 0;
window._detailCurrentImageId = null;

function openDetailModal(index) {
    const images = window.detailViewImages;
    if (!images || !images[index]) return;
    
    window._detailCurrentIndex = index;
    const img = images[index];
    window._detailCurrentImageId = img.id;
    
    const modal = document.getElementById('speedshotDetailModal');
    modal.classList.add('active');
    document.body.style.overflow = 'hidden';
    
    renderDetailModal(img, index);
}

function closeDetailModal() {
    const modal = document.getElementById('speedshotDetailModal');
    modal.classList.remove('active');
    document.body.style.overflow = '';
    window._detailCurrentImageId = null;
}

function detailModalNav(direction) {
    const images = window.detailViewImages;
    if (!images || images.length === 0) return;
    
    let newIndex = window._detailCurrentIndex;
    if (direction === 'prev') {
        newIndex = newIndex > 0 ? newIndex - 1 : images.length - 1;
    } else {
        newIndex = newIndex < images.length - 1 ? newIndex + 1 : 0;
    }
    
    window._detailCurrentIndex = newIndex;
    const img = images[newIndex];
    window._detailCurrentImageId = img.id;
    
    renderDetailModal(img, newIndex);
}

function renderDetailModal(img, index) {
    const images = window.detailViewImages;
    
    // Image
    const imgEl = document.getElementById('detailModalImage');
    const loader = document.querySelector('.detail-modal-image-loader');
    if (loader) loader.style.display = 'flex';
    imgEl.style.opacity = '0';
    
    const tempImg = new Image();
    tempImg.onload = function() {
        imgEl.src = this.src;
        imgEl.alt = img.headline;
        imgEl.style.opacity = '1';
        if (loader) loader.style.display = 'none';
        // Portrait-Klasse für Mobile-Layout
        const section = document.querySelector('.detail-modal-image-section');
        if (section) {
            if (this.naturalHeight > this.naturalWidth) {
                section.classList.add('is-portrait');
            } else {
                section.classList.remove('is-portrait');
            }
        }
    };
    tempImg.onerror = function() {
        imgEl.src = img.thumbnail_url;
        imgEl.style.opacity = '1';
        if (loader) loader.style.display = 'none';
    };
    tempImg.src = img.lightbox_url || img.thumbnail_url;
    
    // Counter
    document.getElementById('detailModalCounter').textContent = (index + 1) + ' / ' + images.length;
    
    // ID
    document.getElementById('detailModalId').textContent = img.id;
    
    // Rating
    const ratingEl = document.getElementById('detailModalRating');
    if (img.rating > 0) {
        ratingEl.textContent = '★'.repeat(img.rating) + '☆'.repeat(5 - img.rating);
        ratingEl.style.display = '';
    } else {
        ratingEl.style.display = 'none';
    }
    
    // Title
    document.getElementById('detailModalTitle').textContent = img.headline;
    
    // Event
    const eventEl = document.getElementById('detailModalEvent');
    if (img.is_all_images && img.event_name) {
        eventEl.style.display = '';
        const link = document.getElementById('detailModalEventLink');
        link.textContent = img.event_name;
        link.href = '?event_id=' + img.event_id;
    } else {
        eventEl.style.display = 'none';
    }
    
    // Description
    const descEl = document.getElementById('detailModalDescription');
    if (img.caption_abstract) {
        descEl.textContent = img.caption_abstract;
        descEl.style.display = '';
    } else {
        descEl.style.display = 'none';
    }
    
    // Players
    const playersSection = document.getElementById('detailModalPlayers');
    const playersList = document.getElementById('detailModalPlayersList');
    if (img.faces && img.faces.length > 0) {
        playersSection.style.display = '';
        playersList.innerHTML = img.faces.map(function(face) {
            const number = face.shirt_number ? '<span class="detail-player-number">#' + escapeHtml(face.shirt_number) + '</span> ' : '';
            const name = img.show_player_names ? escapeHtml(face.name) : '';
            return '<span class="detail-player-tag">' + number + name + '</span>';
        }).join('');
    } else {
        playersSection.style.display = 'none';
    }
    
    // Meta: Datum
    const dateEl = document.getElementById('detailMetaDate');
    if (img.capture_date) {
        dateEl.style.display = '';
        const d = new Date(img.capture_date);
        document.getElementById('detailMetaDateValue').textContent = 
            d.toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric' }) + 
            ' · ' + d.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    } else {
        dateEl.style.display = 'none';
    }
    
    // Meta: Dimensions
    const dimEl = document.getElementById('detailMetaDimensions');
    if (img.width > 0 && img.height > 0) {
        dimEl.style.display = '';
        const mp = ((img.width * img.height) / 1000000).toFixed(1);
        document.getElementById('detailMetaDimensionsValue').textContent = 
            img.width + ' × ' + img.height + ' px (' + mp + ' MP)';
    } else {
        dimEl.style.display = 'none';
    }
    
    
    // Meta: Photographer
    const photoEl = document.getElementById('detailMetaPhotographer');
    if (img.photographer) {
        photoEl.style.display = '';
        document.getElementById('detailMetaPhotographerValue').textContent = img.photographer;
    } else {
        photoEl.style.display = 'none';
    }
    
    // Meta: Copyright
    const copyEl = document.getElementById('detailMetaCopyright');
    if (img.copyright_notice) {
        copyEl.style.display = '';
        document.getElementById('detailMetaCopyrightValue').textContent = img.copyright_notice;
    } else {
        copyEl.style.display = 'none';
    }
    
    // Meta: Top-Bild
    document.getElementById('detailMetaTop').style.display = img.is_top ? '' : 'none';
    
    // Keywords (nur bei Namens-/Freitextsuche und ohne U18-Schutz)
    const kwSection = document.getElementById('detailModalKeywords');
    const kwList = document.getElementById('detailModalKeywordsList');
    if (img.show_keywords && img.keywords) {
        const kws = img.keywords.split(',').map(function(k) { return k.trim(); }).filter(Boolean);
        if (kws.length > 0) {
            kwSection.style.display = '';
            kwList.innerHTML = kws.map(function(k) {
                return '<span class="detail-keyword-tag">' + escapeHtml(k) + '</span>';
            }).join('');
        } else {
            kwSection.style.display = 'none';
        }
    } else {
        kwSection.style.display = 'none';
    }
    
    // Actions: Zeitfenster
    const tfBtn = document.getElementById('detailActionTimeframe');
    tfBtn.onclick = function() {
        closeDetailModal();
        if (typeof openTimeframeModal === 'function') {
            openTimeframeModal(img.id, img.event_id);
        }
    };
    
    // Actions: Merken / Sammlung — TOGGLE
    const bmBtn = document.getElementById('detailActionBookmark');
    const bmSvg = document.getElementById('detailBookmarkSvg');
    const bmText = document.getElementById('detailBookmarkText');
    const bmPath = bmSvg ? bmSvg.querySelector('path') : null;

    function _updateBookmarkBtn(saved) {
        if (saved) {
            bmBtn.classList.add('is-saved');
            if (bmPath) bmPath.setAttribute('fill', 'currentColor');
            bmText.textContent = 'Gemerkt ✓';
            bmBtn.title = 'Aus Sammlung entfernen';
        } else {
            bmBtn.classList.remove('is-saved');
            if (bmPath) bmPath.setAttribute('fill', 'none');
            bmText.textContent = 'Merken';
            bmBtn.title = 'Bild merken (Rechtsklick: Sammlungen)';
        }
    }
    _updateBookmarkBtn(img.in_lightbox);

    bmBtn.onclick = function(e) {
        if (e.button !== 0) return;
        if (img.in_lightbox) {
            // Entfernen — Standard-Collection ID = 0 (default)
            if (typeof removeFromLightbox === 'function') {
                removeFromLightbox(img.id, 0);
            }
            img.in_lightbox = 0;
            _updateBookmarkBtn(false);
            // Sync Card-Button
            if (typeof updateLightboxButtonState === 'function') updateLightboxButtonState(img.id, false);
        } else {
            if (typeof addToLightbox === 'function') {
                addToLightbox(img.id, img.event_id);
            }
            img.in_lightbox = 1;
            _updateBookmarkBtn(true);
            if (typeof updateLightboxButtonState === 'function') updateLightboxButtonState(img.id, true);
        }
    };

    // Actions: Paket — TOGGLE + Sync
    const pkgBtn = document.getElementById('detailActionPackage');

    function _updatePackageBtn(selected) {
        if (selected) {
            pkgBtn.classList.add('is-selected');
            pkgBtn.innerHTML = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><polyline points="9 11 12 14 22 4"/></svg> Im Paket ✓';
        } else {
            pkgBtn.classList.remove('is-selected');
            pkgBtn.innerHTML = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><line x1="12" y1="8" x2="12" y2="16"/><line x1="8" y1="12" x2="16" y2="12"/></svg> Paket';
        }
    }

    const _pkgSelected = typeof PackageSelectionState !== 'undefined'
        ? PackageSelectionState.selectedImages.has(String(img.id))
        : false;
    _updatePackageBtn(_pkgSelected);

    pkgBtn.onclick = function() {
        const card = document.querySelector('[data-image-id="' + img.id + '"]');
        if (card && typeof toggleImageSelection === 'function') {
            toggleImageSelection(card);
            const nowSelected = typeof PackageSelectionState !== 'undefined'
                ? PackageSelectionState.selectedImages.has(String(img.id))
                : false;
            _updatePackageBtn(nowSelected);
        }
    };

    // Actions: Warenkorb — TOGGLE mit direkten Cart-Funktionen (kein Paket-Routing)
    const cartBtn = document.getElementById('detailActionCart');
    const cartText = document.getElementById('detailCartBtnText');

    function _updateCartBtn(inCart) {
        if (inCart) {
            cartBtn.classList.add('in-cart');
            cartBtn.disabled = false;
            cartText.textContent = 'Im Warenkorb ✗ entfernen';
            cartBtn.title = 'Aus Warenkorb entfernen';
        } else {
            cartBtn.classList.remove('in-cart');
            cartBtn.disabled = false;
            cartText.textContent = img.shop_price
                ? 'Warenkorb (' + parseFloat(img.shop_price).toFixed(2).replace('.', ',') + ' €)'
                : 'Warenkorb';
            cartBtn.title = 'In den Warenkorb';
        }
    }
    _updateCartBtn(img.in_cart);

    cartBtn.onclick = function() {
        if (img.in_cart) {
            _updateCartBtn(false); // Optimistisches UI-Update
            window.removeDirectFromCart(img.id).catch(function() {
                _updateCartBtn(true); // Rollback bei Fehler
            });
            img.in_cart = 0;
            // Sync Card
            var card = document.querySelector('[data-image-id="' + img.id + '"]');
            if (card) card.setAttribute('data-in-cart', '0');
        } else {
            if (typeof window.addDirectToCart === 'function') {
                _updateCartBtn(true); // Optimistisches UI-Update
                window.addDirectToCart({
                    id:        img.id,
                    title:     img.headline,
                    price:     img.shop_price,
                    thumbnail: img.thumbnail_url
                }).then(function(result) {
                    if (!result) { _updateCartBtn(false); img.in_cart = 0; }
                }).catch(function() { _updateCartBtn(false); img.in_cart = 0; });
                img.in_cart = 1;
                var card = document.querySelector('[data-image-id="' + img.id + '"]');
                if (card) card.setAttribute('data-in-cart', '1');
            }
        }
    };
}

function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

// Keyboard Navigation
document.addEventListener('keydown', function(e) {
    const modal = document.getElementById('speedshotDetailModal');
    if (!modal || !modal.classList.contains('active')) return;
    
    if (e.key === 'Escape') { closeDetailModal(); e.preventDefault(); }
    if (e.key === 'ArrowLeft') { detailModalNav('prev'); e.preventDefault(); }
    if (e.key === 'ArrowRight') { detailModalNav('next'); e.preventDefault(); }
});

// Swipe Support (Touch) – Horizontal: Navigation, Vertikal: Schließen
(function() {
    let touchStartX = 0;
    let touchStartY = 0;
    let touchStartTime = 0;
    const modal = document.getElementById('speedshotDetailModal');
    if (!modal) return;
    
    modal.addEventListener('touchstart', function(e) {
        touchStartX = e.changedTouches[0].screenX;
        touchStartY = e.changedTouches[0].screenY;
        touchStartTime = Date.now();
    }, { passive: true });
    
    modal.addEventListener('touchend', function(e) {
        const diffX = e.changedTouches[0].screenX - touchStartX;
        const diffY = e.changedTouches[0].screenY - touchStartY;
        const elapsed = Date.now() - touchStartTime;
        
        // Nur schnelle Swipes (< 400ms)
        if (elapsed > 400) return;
        
        // Vertikal nach unten > 80px → Schließen
        if (diffY > 80 && Math.abs(diffY) > Math.abs(diffX)) {
            closeDetailModal();
            return;
        }
        
        // Horizontal swipen (nicht vertikal scrollen)
        if (Math.abs(diffX) > Math.abs(diffY) && Math.abs(diffX) > 50) {
            if (diffX > 0) detailModalNav('prev');
            else detailModalNav('next');
        }
    }, { passive: true });
})();
</script>

<style>
