/**
 * Cart-Toggle für Gallery-Card Buttons
 */
window.galleryCardCartToggle = function(btn) {
    var card = btn.closest('.gallery-card');
    var id   = parseInt(btn.dataset.imageId);
    var svgCart = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/></svg>';
    var svgCheck = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>';

    if (btn.classList.contains('in-cart')) {
        // Entfernen
        btn.disabled = true;
        window.removeDirectFromCart(id).then(function() {
            btn.classList.remove('in-cart');
            btn.title = 'In Warenkorb';
            btn.innerHTML = svgCart;
            btn.disabled = false;
            if (card) card.setAttribute('data-in-cart', '0');
            // Sync detailViewImages
            if (window.detailViewImages) {
                var entry = window.detailViewImages.find(function(i){ return i.id == id; });
                if (entry) entry.in_cart = 0;
            }
        }).catch(function() { btn.disabled = false; });
    } else {
        // Hinzufügen – direkt, KEIN Paket-Routing
        window.addDirectToCart({
            id:        id,
            title:     btn.dataset.title,
            price:     btn.dataset.price,
            thumbnail: btn.dataset.thumbnail
        }, btn).then(function(result) {
            if (result) {
                btn.classList.add('in-cart');
                btn.title = 'Im Warenkorb – klicken zum Entfernen';
                btn.innerHTML = svgCheck;
                if (card) card.setAttribute('data-in-cart', '1');
                // Sync detailViewImages
                if (window.detailViewImages) {
                    var entry = window.detailViewImages.find(function(i){ return i.id == id; });
                    if (entry) entry.in_cart = 1;
                }
            }
        }).catch(function(){});
    }
};

// Event Delegation für Gallery Cards → Detail Modal öffnen
document.addEventListener('DOMContentLoaded', function() {
    var galleryGrid = document.querySelector('.galerie-grid.layout-gallery');
    if (!galleryGrid) return;
    
    galleryGrid.addEventListener('click', function(e) {
        // ID-Badge Klick nicht weiterleiten (hat eigenen stopPropagation)
        if (e.target.closest('.gallery-card-id-badge')) return;
        // Action-Buttons nicht weiterleiten
        if (e.target.closest('.gallery-card-actions')) return;
        
        var card = e.target.closest('.gallery-card');
        if (!card) return;
        
        var index = parseInt(card.getAttribute('data-index'), 10);
        if (typeof openDetailModal === 'function') {
            openDetailModal(index);
        } else {
            console.error('openDetailModal nicht verfügbar');
        }
    });
});

/**
 * Direkt zum Warenkorb hinzufügen – OHNE Paket-Logik-Bypass
 * Nutzt SpeedShot_Shop_AddToCart falls verfügbar
 */
window.addDirectToCart = function(imageData, btnEl) {
    if (typeof SpeedShot_Shop_AddToCart === 'undefined') {
        console.error('[CART] Shop-Plugin nicht installiert');
        return Promise.reject('no shop');
    }
    if (btnEl) { btnEl.disabled = true; btnEl.style.opacity = '0.6'; }

    const data = {
        image_id: imageData.id,
        title:    imageData.title,
        price:    parseFloat(imageData.price || 0),
        thumbnail_url: imageData.thumbnail || ''
    };

    return SpeedShot_Shop_AddToCart('image', data)
        .then(function(result) {
            if (btnEl) { btnEl.disabled = false; btnEl.style.opacity = ''; }
            return result;
        })
        .catch(function(err) {
            console.error('[CART] Add error:', err);
            if (btnEl) { btnEl.disabled = false; btnEl.style.opacity = ''; }
            throw err;
        });
};

/**
 * Aus dem Shop-Warenkorb entfernen anhand image_id
 * Nutzt AJAX action speedshot_shop_remove_from_cart
 */
window.removeDirectFromCart = function(imageId) {
    const nonce = (typeof speedshot_gallery_data !== 'undefined' && speedshot_gallery_data.shop_nonce)
        ? speedshot_gallery_data.shop_nonce
        : ((typeof speedshotShop !== 'undefined' && speedshotShop.nonce) ? speedshotShop.nonce : '');

    const ajaxUrl = (typeof speedshot_gallery_data !== 'undefined' && speedshot_gallery_data.ajax_url)
        ? speedshot_gallery_data.ajax_url
        : '/wp-admin/admin-ajax.php';

    // Versuche zuerst den alten toggleCart (einfacheres System)
    if (typeof toggleCart === 'function' && (typeof SpeedShot_Shop_AddToCart === 'undefined')) {
        toggleCart(imageId);
        return Promise.resolve();
    }

    // Shop-System: Finde cart_item_id über den Cart
    return fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
            action: 'speedshot_shop_get_cart',
            nonce:  nonce
        })
    })
    .then(r => r.json())
    .then(data => {
        if (!data.success || !data.data || !data.data.items) {
            // Fallback: toggleCart
            if (typeof toggleCart === 'function') toggleCart(imageId);
            return;
        }
        const item = data.data.items.find(function(i) {
            return String(i.product_data && (i.product_data.image_id || i.product_data.id)) === String(imageId);
        });
        if (!item) { console.warn('[CART] Item not found for image', imageId); return; }

        return fetch(ajaxUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams({
                action:  'speedshot_shop_remove_from_cart',
                item_id: item.id,
                nonce:   nonce
            })
        }).then(r => r.json()).then(function(res) {
            if (res.success && typeof window.speedshotShopUpdateCartCount === 'function') {
                window.speedshotShopUpdateCartCount();
            }
        });
    })
    .catch(err => console.error('[CART] Remove error:', err));
};
</script>

<style>
/* ================================================================
