}

.gallery-card-aspect {
    position: relative;
    width: 100%;
    aspect-ratio: 1 / 1; /* Immer quadratisch */
    overflow: hidden;
}

.gallery-card-aspect .gallery-card-image {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    object-fit: cover; /* Bild wird zugeschnitten – quadratisch, kein Letterbox */
    transition: transform 0.3s ease;
}

.gallery-card:hover .gallery-card-image {
