<!-- Lightbox -->

<div class="galerie-lightbox-overlay" id="speedshotLightbox">
    <button class="lightbox-close" onclick="closeLightbox()">
        <i class="bi bi-x-lg"></i>
    </button>
    <button class="lightbox-nav lightbox-prev" onclick="lightboxNav('prev')">
        <i class="bi bi-chevron-left"></i>
    </button>
    <button class="lightbox-nav lightbox-next" onclick="lightboxNav('next')">
        <i class="bi bi-chevron-right"></i>
    </button>
    <div class="lightbox-image-container">
        <img id="lightboxImage" src="" alt="">
        <div class="lightbox-loader" id="galerieLightboxLoader">
            <div class="spinner"></div>
        </div>
    </div>
    <div class="lightbox-info-bar" id="galerieLightboxInfo">
        <div class="lightbox-info-left">
            <span id="lightboxInfoTitle" class="lightbox-info-title"></span>
            <span id="lightboxInfoPlayers" class="lightbox-info-players"></span>
            <span id="lightboxInfoRating" class="lightbox-info-rating"></span>
        </div>
        <div class="lightbox-info-right">
            <button class="btn-mgmt btn-sm" id="lightboxSaveBtn" onclick="addToLightboxFromViewer()" title="Bild merken">
                <i class="bi bi-bookmark"></i> Merken
            </button>
            <button class="btn-mgmt btn-primary btn-sm" id="lightboxCartBtn" onclick="lightboxAddToCart()">
                <i class="bi bi-cart-plus"></i> In Warenkorb
            </button>
        </div>
    </div>
</div>

<script>
// ========================================================================
// GALERIE LIGHTBOX v6.0
// ========================================================================

window.currentLightboxImageId = null;
var galerieLightboxImages = [];

function findImageCard(imageId) {
    return document.querySelector('.speedshot-image-card[data-image-id="' + imageId + '"]') ||
           document.querySelector('.speedshot-grid-card[data-image-id="' + imageId + '"]');
}

function openLightbox(imageId) {
    var lightbox = document.getElementById('speedshotLightbox');
    if (!lightbox) return;

    var imageCard = findImageCard(imageId);
    if (!imageCard) return;

    // Sammle alle sichtbaren Bild-IDs fuer Navigation
    var allCards = document.querySelectorAll('.speedshot-image-card, .speedshot-grid-card');
    galerieLightboxImages = [];
    allCards.forEach(function(card) { galerieLightboxImages.push(parseInt(card.dataset.imageId)); });

    window.currentLightboxImageId = imageId;
    loadGalerieLightboxImage(imageCard);
    lightbox.classList.add('open');
    document.body.style.overflow = 'hidden';
}

function closeLightbox() {
    var lightbox = document.getElementById('speedshotLightbox');
    if (lightbox) lightbox.classList.remove('open');
    document.body.style.overflow = '';
    window.currentLightboxImageId = null;
}

function loadGalerieLightboxImage(imageCard) {
    var img = document.getElementById('lightboxImage');
    var loader = document.getElementById('galerieLightboxLoader');
    var lightboxUrl = imageCard.dataset.lightboxUrl;

    if (!lightboxUrl) return;

    // Loader anzeigen
    if (loader) loader.classList.add('active');
    img.style.opacity = '0';

    var tempImg = new Image();
    tempImg.onload = function() {
        img.src = this.src;
        img.alt = imageCard.dataset.imageTitle || '';
        img.style.opacity = '1';
        if (loader) loader.classList.remove('active');
    };
    tempImg.onerror = function() {
        if (loader) loader.classList.remove('active');
        img.style.opacity = '1';
    };
    tempImg.src = lightboxUrl;

    // Info-Bar aktualisieren
    var titleEl = document.getElementById('lightboxInfoTitle');
    var playersEl = document.getElementById('lightboxInfoPlayers');
    var ratingEl = document.getElementById('lightboxInfoRating');

    if (titleEl) titleEl.textContent = imageCard.dataset.imageTitle || 'Bild #' + imageCard.dataset.imageId;

    var cardPlayers = imageCard.querySelector('.card-players, .card-players-center');
    if (playersEl) playersEl.textContent = cardPlayers ? cardPlayers.textContent.trim() : '';

    var cardRating = imageCard.querySelector('.card-rating, .grid-card-rating-badge');
    if (ratingEl) {
        if (cardRating) {
            ratingEl.innerHTML = cardRating.innerHTML;
            ratingEl.style.display = '';
        } else {
            ratingEl.style.display = 'none';
        }
    }

    // Button-Status aktualisieren
    updateGalerieLightboxButtons(imageCard);

    // Navigation Buttons ein-/ausblenden
    var currentIndex = galerieLightboxImages.indexOf(parseInt(imageCard.dataset.imageId));
    var prevBtn = document.querySelector('#speedshotLightbox .lightbox-prev');
    var nextBtn = document.querySelector('#speedshotLightbox .lightbox-next');
    if (prevBtn) prevBtn.style.display = galerieLightboxImages.length > 1 ? '' : 'none';
    if (nextBtn) nextBtn.style.display = galerieLightboxImages.length > 1 ? '' : 'none';
}

function updateGalerieLightboxButtons(imageCard) {
    var cartBtn = document.getElementById('lightboxCartBtn');
    var saveBtn = document.getElementById('lightboxSaveBtn');

    // Warenkorb-Status
    if (cartBtn) {
        var inCart = imageCard.dataset.inCart === '1';
        if (inCart) {
            cartBtn.innerHTML = '<i class="bi bi-cart-check"></i> Im Warenkorb';
            cartBtn.disabled = true;
            cartBtn.classList.add('btn-disabled');
        } else {
            cartBtn.innerHTML = '<i class="bi bi-cart-plus"></i> In Warenkorb';
            cartBtn.disabled = false;
            cartBtn.classList.remove('btn-disabled');
        }
    }

    // Merken-Status
    if (saveBtn) {
        var savedBtn = imageCard.querySelector('.btn-lightbox.is-saved');
        if (savedBtn) {
            saveBtn.innerHTML = '<i class="bi bi-bookmark-fill"></i> Gemerkt';
            saveBtn.classList.add('btn-saved');
        } else {
            saveBtn.innerHTML = '<i class="bi bi-bookmark"></i> Merken';
            saveBtn.classList.remove('btn-saved');
        }
    }
}

function lightboxNav(direction) {
    var currentIndex = galerieLightboxImages.indexOf(window.currentLightboxImageId);
    var newIndex;

    if (direction === 'prev') {
        newIndex = currentIndex > 0 ? currentIndex - 1 : galerieLightboxImages.length - 1;
    } else {
        newIndex = currentIndex < galerieLightboxImages.length - 1 ? currentIndex + 1 : 0;
    }

    window.currentLightboxImageId = galerieLightboxImages[newIndex];
    var imageCard = findImageCard(window.currentLightboxImageId);
    if (imageCard) loadGalerieLightboxImage(imageCard);
}

function lightboxAddToCart() {
    var btn = document.getElementById('lightboxCartBtn');
    if (!btn || btn.disabled) return;

    var imageCard = findImageCard(window.currentLightboxImageId);
    if (!imageCard) return;

    var shopData = {
        image_id: parseInt(imageCard.dataset.imageId),
        title: imageCard.dataset.shopTitle || imageCard.dataset.imageTitle || 'Bild #' + imageCard.dataset.imageId,
        price: parseFloat(imageCard.dataset.shopPrice) || 0,
        thumbnail_url: imageCard.dataset.shopThumbnail || imageCard.dataset.imageSrc || ''
    };

    // Shop-Plugin verfuegbar?
    if (typeof SpeedShot_Shop_AddToCart !== 'undefined') {
        var originalHtml = btn.innerHTML;
        btn.innerHTML = '<i class="bi bi-hourglass-split"></i>';
        btn.disabled = true;

        SpeedShot_Shop_AddToCart('image', shopData)
            .then(function(result) {
                btn.innerHTML = '<i class="bi bi-cart-check"></i> Im Warenkorb';
                btn.classList.add('btn-disabled');
                btn.disabled = true;
                imageCard.dataset.inCart = '1';
                if (typeof updateCardCartStatus === 'function') updateCardCartStatus(imageCard, true);
            })
            .catch(function(err) {
                btn.innerHTML = originalHtml;
                btn.disabled = false;
            });
    } else if (typeof window.addImageToShopCart === 'function') {
        window.addImageToShopCart({ id: shopData.image_id, title: shopData.title, price: shopData.price, thumbnail: shopData.thumbnail_url });
        btn.innerHTML = '<i class="bi bi-cart-check"></i> Im Warenkorb';
        btn.classList.add('btn-disabled');
        btn.disabled = true;
        imageCard.dataset.inCart = '1';
    }
}

// Keyboard Navigation
document.addEventListener('keydown', function(e) {
    var lightbox = document.getElementById('speedshotLightbox');
    if (!lightbox || !lightbox.classList.contains('open')) return;

    if (e.key === 'Escape') closeLightbox();
    else if (e.key === 'ArrowLeft') lightboxNav('prev');
    else if (e.key === 'ArrowRight') lightboxNav('next');
});
</script>

