/* Hover Preview im Modal: z-index muss über Modal (10000) liegen */
.timeframe-modal ~ .image-hover-preview,
.image-hover-preview.tf-active {
    z-index: 10001 !important;
}
</style>

<script>
let currentTimeframeImageId = null;
let currentTimeframeEventId = null;
let currentTimeframeSeconds = 30;
let currentTimeframeDirection = 'both';
let timeframeImagesData = [];
let timeframeMode = 'relative'; // 'relative' oder 'range'
let timeframeHistory = []; // Stack für Zurück-Navigation
let timeframeFirstImageTime = null;
let timeframeLastImageTime = null;

function openTimeframeModal(imageId, eventId) {
    currentTimeframeImageId = imageId;
    currentTimeframeEventId = eventId;
    currentTimeframeSeconds = 30;
    currentTimeframeDirection = 'both';
    timeframeImagesData = [];
    timeframeHistory = [];
    timeframeMode = 'relative';
    
    const modal = document.getElementById('timeframeModal');
    modal.style.display = 'flex';
    document.body.style.overflow = 'hidden';
    
    // Reset UI
    document.querySelectorAll('.timeframe-btn').forEach(btn => {
        btn.classList.remove('active');
        if (parseInt(btn.dataset.seconds) === 30) {
            btn.classList.add('active');
        }
    });
    
    document.querySelectorAll('.direction-btn').forEach(btn => {
        btn.classList.remove('active');
        if (btn.dataset.direction === 'both') {
            btn.classList.add('active');
        }
    });
    
    // Mode Reset
    switchTimeframeMode('relative', true);
    
    // Reset Suche
    resetTimeframeSearch();
    
    // Reset Back-Button
    document.getElementById('timeframeBackBtn').style.display = 'none';
    document.getElementById('timeframeTitle').textContent = 'Bilder im gleichen Zeitfenster';
    document.getElementById('timeframeRefInfo').style.display = 'none';
    
    // Scroll nach oben
    const scrollArea = document.getElementById('timeframeScrollArea');
    if (scrollArea) scrollArea.scrollTop = 0;
    
    // Lade Bilder
    loadTimeframeImages();
}

function closeTimeframeModal() {
    const modal = document.getElementById('timeframeModal');
    modal.style.display = 'none';
    document.body.style.overflow = '';
    
    // Hover Preview verstecken und z-index zurücksetzen
    tfHidePreview();
    const preview = document.getElementById('imageHoverPreview');
    if (preview) preview.style.zIndex = '';
}

/* ========== MODUS-UMSCHALTER ========== */
function switchTimeframeMode(mode, skipLoad) {
    timeframeMode = mode;
    
    document.querySelectorAll('.mode-btn').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.mode === mode);
    });
    
    document.getElementById('timeframeRelativeControls').style.display = mode === 'relative' ? '' : 'none';
    document.getElementById('timeframeRangeControls').style.display = mode === 'range' ? '' : 'none';
    
    // Navigation nur im relativen Modus
    const nav = document.getElementById('timeframeNavigation');
    if (nav && mode === 'range') nav.style.display = 'none';
    
    if (!skipLoad && mode === 'relative' && currentTimeframeImageId) {
        loadTimeframeImages();
    }
}

/* ========== ZEITBEREICH-MODUS ========== */
function loadTimeRangeImages() {
    const timeFrom = document.getElementById('timeframeRangeFrom').value; // "HH:MM:SS" oder "HH:MM"
    const timeTo = document.getElementById('timeframeRangeTo').value;
    
    if (!timeFrom && !timeTo) {
        alert('Bitte mindestens eine Uhrzeit angeben.');
        return;
    }
    
    // Event-Datum aus SpeedShotGalerie (z.B. "2024-06-15")
    const eventDate = (typeof SpeedShotGalerie !== 'undefined' && SpeedShotGalerie.eventDate) 
        ? SpeedShotGalerie.eventDate 
        : new Date().toISOString().split('T')[0];
    
    // Kombiniere Datum + Uhrzeit → "2024-06-15 14:30:00"
    const fullFrom = timeFrom ? `${eventDate} ${timeFrom}` : '';
    const fullTo = timeTo ? `${eventDate} ${timeTo}` : '';
    
    const loading = document.getElementById('timeframeLoading');
    const grid = document.getElementById('timeframeImagesGrid');
    const noImages = document.getElementById('timeframeNoImages');
    const nav = document.getElementById('timeframeNavigation');
    const count = document.getElementById('timeframeRangeCount');
    
    loading.style.display = 'block';
    grid.style.display = 'none';
    noImages.style.display = 'none';
    if (nav) nav.style.display = 'none';
    count.textContent = 'Lädt...';
    
    resetTimeframeSearch();
    
    const formData = new FormData();
    formData.append('action', 'speedshot_load_timeframe_images');
    formData.append('nonce', SpeedShotGalerie.nonce);
    formData.append('event_id', currentTimeframeEventId);
    formData.append('image_id', 0);
    formData.append('seconds', 0);
    formData.append('direction', 'both');
    
    if (fullFrom) formData.append('time_from', fullFrom);
    if (fullTo) formData.append('time_to', fullTo);
    
    fetch(SpeedShotGalerie.ajaxUrl, {
        method: 'POST',
        body: formData
    })
    .then(response => response.json())
    .then(data => {
        loading.style.display = 'none';
        
        if (data.success && data.data.images.length > 0) {
            timeframeImagesData = data.data.images;
            renderTimeframeGrid(data.data.images, false);
            count.textContent = `${data.data.count} Bild${data.data.count !== 1 ? 'er' : ''} gefunden`;
        } else {
            noImages.style.display = 'block';
            count.textContent = '0 Bilder gefunden';
        }
    })
    .catch(error => {
        console.error('Error loading time range images:', error);
        loading.style.display = 'none';
        noImages.style.display = 'block';
        count.textContent = 'Fehler';
    });
}

/* ========== RELATIVER MODUS ========== */
function changeTimeframe(seconds) {
    currentTimeframeSeconds = seconds;
    
    document.querySelectorAll('.timeframe-btn').forEach(btn => {
        btn.classList.remove('active');
        if (parseInt(btn.dataset.seconds) === seconds) {
            btn.classList.add('active');
        }
    });
    
    loadTimeframeImages();
}

function changeDirection(direction) {
    currentTimeframeDirection = direction;
    
    document.querySelectorAll('.direction-btn').forEach(btn => {
        btn.classList.remove('active');
        if (btn.dataset.direction === direction) {
            btn.classList.add('active');
        }
    });
    
    loadTimeframeImages();
}

function loadTimeframeImages() {
    const loading = document.getElementById('timeframeLoading');
    const grid = document.getElementById('timeframeImagesGrid');
    const noImages = document.getElementById('timeframeNoImages');
    const nav = document.getElementById('timeframeNavigation');
    const count = document.getElementById('timeframeCount');
    
    loading.style.display = 'block';
    grid.style.display = 'none';
    noImages.style.display = 'none';
    if (nav) nav.style.display = 'none';
    count.textContent = 'Lädt...';
    
    resetTimeframeSearch();
    
    const formData = new FormData();
    formData.append('action', 'speedshot_load_timeframe_images');
    formData.append('nonce', SpeedShotGalerie.nonce);
    formData.append('event_id', currentTimeframeEventId);
    formData.append('image_id', currentTimeframeImageId);
    formData.append('seconds', currentTimeframeSeconds);
    formData.append('direction', currentTimeframeDirection);
    
    fetch(SpeedShotGalerie.ajaxUrl, {
        method: 'POST',
        body: formData
    })
    .then(response => response.json())
    .then(data => {
        loading.style.display = 'none';
        
        if (data.success && data.data.images.length > 0) {
            timeframeImagesData = data.data.images;
            renderTimeframeGrid(data.data.images, true);
            count.textContent = `${data.data.count} Bild${data.data.count !== 1 ? 'er' : ''} gefunden`;
            
            // Referenzbild-Info aktualisieren wenn re-centered
            updateRefInfo();
        } else {
            noImages.style.display = 'block';
            count.textContent = '0 Bilder gefunden';
        }
    })
    .catch(error => {
        console.error('Error loading timeframe images:', error);
        loading.style.display = 'none';
        noImages.style.display = 'block';
        count.textContent = 'Fehler beim Laden';
    });
}

/* ========== GRID RENDERN ========== */
function renderTimeframeGrid(images, showNavigation) {
    const grid = document.getElementById('timeframeImagesGrid');
    const nav = document.getElementById('timeframeNavigation');
    
    grid.innerHTML = '';
    
    // Track erste und letzte Bildzeit für Navigation
    timeframeFirstImageTime = null;
    timeframeLastImageTime = null;
    
    images.forEach((image, index) => {
        const item = createTimeframeImageItem(image);
        grid.appendChild(item);
        
        // Speichere capture_date/created_at für Navigation
        const imageTime = image.capture_date || image.created_at;
        if (imageTime) {
            if (index === 0) timeframeFirstImageTime = imageTime;
            timeframeLastImageTime = imageTime;
        }
        // Speichere auch IDs für Navigation
        if (index === 0) item.dataset.firstImage = '1';
        if (index === images.length - 1) item.dataset.lastImage = '1';
    });
    
    grid.style.display = 'block';
    
    // Navigation anzeigen im relativen Modus
    if (showNavigation && nav && timeframeMode === 'relative') {
        nav.style.display = 'flex';
        updateNavButtons();
    }
    
    updateMasonryColumns();
    document.getElementById('timeframeScrollArea').scrollTop = 0;
}

/* ========== REFERENZBILD-INFO ========== */
function updateRefInfo() {
    const refInfo = document.getElementById('timeframeRefInfo');
    const backBtn = document.getElementById('timeframeBackBtn');
    
    if (timeframeHistory.length > 0) {
        refInfo.style.display = 'flex';
        document.getElementById('timeframeRefId').textContent = `#${currentTimeframeImageId}`;
        backBtn.style.display = 'flex';
    } else {
        refInfo.style.display = 'none';
        backBtn.style.display = 'none';
    }
}

/* ========== NAVIGATION: WEITER/ZURÜCK ========== */
function updateNavButtons() {
    const nav = document.getElementById('timeframeNavigation');
    if (!nav) return;
    
    const info = document.getElementById('tfNavInfo');
    const count = timeframeImagesData.length;
    
    if (count > 0) {
        info.textContent = `${count} Bild${count !== 1 ? 'er' : ''} angezeigt`;
    }
}

function timeframeNavigate(direction) {
    // Bestimme welches Bild als neues Zentrum dient
    let pivotImage = null;
    
    if (direction === 'future' && timeframeImagesData.length > 0) {
        // Letztes Bild als neues Zentrum
        pivotImage = timeframeImagesData[timeframeImagesData.length - 1];
    } else if (direction === 'past' && timeframeImagesData.length > 0) {
        // Erstes Bild als neues Zentrum
        pivotImage = timeframeImagesData[0];
    }
    
    if (!pivotImage) return;
    
    // Aktuelles Bild auf History-Stack
    timeframeHistory.push(currentTimeframeImageId);
    
    // Neues Zentrum setzen
    currentTimeframeImageId = pivotImage.id;
    
    loadTimeframeImages();
}

/* ========== RE-CENTER: Bild anklicken → neues Zentrum ========== */
function recenterTimeframe(imageId) {
    if (!imageId || imageId === currentTimeframeImageId) return;
    
    // Aktuelles auf Stack
    timeframeHistory.push(currentTimeframeImageId);
    
    // Neues Zentrum
    currentTimeframeImageId = imageId;
    
    // Wechsel in relativen Modus falls nötig
    if (timeframeMode !== 'relative') {
        switchTimeframeMode('relative', true);
    }
    
    loadTimeframeImages();
}

/* ========== ZURÜCK-NAVIGATION ========== */
function timeframeGoBack() {
    if (timeframeHistory.length === 0) return;
    
    currentTimeframeImageId = timeframeHistory.pop();
    loadTimeframeImages();
}

/* ========== BILD-ITEM ERSTELLEN ========== */
function createTimeframeImageItem(image) {
    const div = document.createElement('div');
    div.className = 'timeframe-image-item';
    div.dataset.imageId = image.id;
    div.dataset.imageSrc = image.thumbnail_url || '';
    div.dataset.imageTitle = image.headline || image.players || `Bild #${image.id}`;
    div.dataset.imagePrice = image.price || '0.00';
    if (image.capture_date || image.created_at) div.dataset.createdAt = image.capture_date || image.created_at;
    
    // Suchbare Daten: Name, Trikotnummer, Keywords, Beschreibung, Teams, Headline
    const searchParts = [
        image.players || '',
        image.headline || '',
        image.description || '',
        image.beschreibung || '',
        image.teams || '',
        image.photographer || '',
        image.keywords || '',
        image.shirt_numbers || ''
    ];
    
    // Auch einzelne Trikotnummern aus faces
    if (image.faces && Array.isArray(image.faces)) {
        image.faces.forEach(f => {
            if (f.shirt_number) searchParts.push(f.shirt_number);
            if (f.name) searchParts.push(f.name);
        });
    }
    
    div.dataset.search = searchParts.join(' ').toLowerCase();
    
    // Time difference
    const timeDiff = Math.abs(image.time_diff || 0);
    const timeSign = (image.time_diff || 0) < 0 ? '-' : '+';
    const timeStr = timeDiff < 60 ? `${timeDiff}s` : `${Math.floor(timeDiff / 60)}m ${timeDiff % 60}s`;
    
    // Uhrzeit anzeigen
    let clockTime = '';
    const displayTime = image.capture_date || image.created_at;
    if (displayTime) {
        const parts = displayTime.split(' ');
        if (parts[1]) clockTime = parts[1].substring(0, 8);
    }
    
    const players = image.players || '';
    const hasShop = typeof addImageToShopCart === 'function';
    const hasPackages = typeof toggleImageSelection === 'function'
        && (typeof PackageSelectionState === 'undefined' || PackageSelectionState.packagesAvailable !== false);
    
    // Prüfe ob bereits im Paket selektiert
    const isSelected = typeof PackageSelectionState !== 'undefined' 
        && PackageSelectionState.selectedImages 
        && PackageSelectionState.selectedImages.has(String(image.id));
    
    const existingCard = document.querySelector(`[data-image-id="${image.id}"]`);
    const inCart = existingCard ? existingCard.dataset.inCart === '1' : false;
    
    // Klasse für bereits selektierte Bilder
    if (isSelected) {
        div.classList.add('image-selected');
    }
    
    const shopData = {
        id: image.id,
        title: image.headline || image.players || `Bild #${image.id}`,
        price: parseFloat(image.price || 5.99),
        thumbnail: image.thumbnail_url || ''
    };
    
    // Time Badge: zeige Uhrzeit + Differenz
    const timeBadgeText = timeframeMode === 'range' && clockTime 
        ? clockTime 
        : `${timeSign}${timeStr}`;
    
    // Lightbox/Preview URL (größeres Bild)
    const previewUrl = (image.lightbox_url || image.thumbnail_url || '').replace(/'/g, "\\'");
    
    div.innerHTML = `
        <img src="${image.thumbnail_url}" alt="Bild #${image.id}" loading="lazy" 
             onload="this.parentElement.classList.add('loaded')"
             onmouseenter="tfShowPreview('${previewUrl}')"
             onmouseleave="tfHidePreview()">
        
        <!-- Time Badge -->
        <span class="timeframe-time-badge"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:-1px;margin-right:3px;"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>${timeBadgeText}</span>
        
        <!-- Action Buttons -->
        <div class="timeframe-image-actions">
            ${hasPackages ? `
            <button class="card-btn btn-package ${isSelected ? 'is-selected' : ''}" 
                    onclick="event.stopPropagation(); toggleTimeframeImageSelection(this.closest('.timeframe-image-item'));"
                    title="${isSelected ? 'Aus Paket entfernen' : 'Zum Paket hinzufügen'}"
                    ${inCart ? 'style="display:none"' : ''}>
                ${isSelected 
                    ? '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"/></svg>'
                    : '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><line x1="12" y1="8" x2="12" y2="16"/><line x1="8" y1="12" x2="16" y2="12"/></svg>'
                }
            </button>
            ` : ''}
            ${hasShop ? `
            <button class="card-btn btn-shop ${inCart ? 'in-cart' : ''}" 
                    ${!inCart ? `onclick='event.stopPropagation(); addImageToShopCart(${JSON.stringify(shopData)});'` : 'disabled'}
                    title="${inCart ? 'Im Warenkorb' : 'In Warenkorb'}"
                    ${isSelected && !inCart ? 'style="display:none"' : ''}>
                ${inCart ? '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"/></svg>' : '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/></svg>'}
            </button>
            ` : ''}
        </div>
        
        <!-- Re-center Button -->
        <button class="timeframe-image-recenter" 
                onclick="event.stopPropagation(); recenterTimeframe(${image.id});"
                title="Von hier aus suchen">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="3"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/></svg>
        </button>
        
        <!-- Overlay unten -->
        <div class="timeframe-image-overlay" onclick="openLightbox(${image.id});">
            ${players ? `<div class="timeframe-image-players"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:-1px;margin-right:3px;"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>${players}</div>` : ''}
            ${clockTime && timeframeMode !== 'range' ? `<div class="timeframe-image-players" style="opacity:0.7;">${clockTime}</div>` : ''}
        </div>
    `;
    
    return div;
}

/* ========== SUCHE (erweitert) ========== */
let timeframeSearchTimeout = null;

function getActiveSearchInput() {
    if (timeframeMode === 'range') {
        return document.getElementById('timeframeRangeSearchInput');
    }
    return document.getElementById('timeframeSearchInput');
}

function getActiveClearBtn() {
    if (timeframeMode === 'range') {
        return document.getElementById('timeframeRangeSearchClear');
    }
    return document.getElementById('timeframeSearchClear');
}

function getActiveFilterCount() {
    if (timeframeMode === 'range') {
        return document.getElementById('timeframeRangeFilterCount');
    }
    return document.getElementById('timeframeFilterCount');
}

function filterTimeframeImages() {
    const input = getActiveSearchInput();

    const clearBtn = getActiveClearBtn();
    const filterCount = getActiveFilterCount();
    
    if (!input) return;
    
    const query = input.value.trim().toLowerCase();
    
    if (clearBtn) clearBtn.style.display = query.length > 0 ? 'block' : 'none';
    
    // Debounce
    clearTimeout(timeframeSearchTimeout);
    timeframeSearchTimeout = setTimeout(() => {
        const items = document.querySelectorAll('#timeframeImagesGrid .timeframe-image-item');
        let visible = 0;
        const total = items.length;
        
        // Mehrere Suchbegriffe mit Leerzeichen trennen (AND-Verknüpfung)
        const terms = query.split(/\s+/).filter(t => t.length > 0);
        
        items.forEach(item => {
            if (terms.length === 0) {
                item.classList.remove('tf-hidden');
                visible++;
            } else {
                const searchData = item.dataset.search || '';
                const allMatch = terms.every(term => searchData.includes(term));
                if (allMatch) {
                    item.classList.remove('tf-hidden');
                    visible++;
                } else {
                    item.classList.add('tf-hidden');
                }
            }
        });
        
        if (filterCount) {
            if (terms.length > 0) {
                filterCount.textContent = `${visible} von ${total} angezeigt`;
                filterCount.style.display = 'inline';
            } else {
                filterCount.style.display = 'none';
            }
        }
        
        // Spaltenanzahl anpassen
        updateMasonryColumns();
    }, 150);
}

function clearTimeframeSearch() {
    const input = getActiveSearchInput();
    if (input) {
        input.value = '';
        input.focus();
    }
    filterTimeframeImages();
}

function resetTimeframeSearch() {
    ['timeframeSearchInput', 'timeframeRangeSearchInput'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = '';
    });
    ['timeframeSearchClear', 'timeframeRangeSearchClear'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.style.display = 'none';
    });
    ['timeframeFilterCount', 'timeframeRangeFilterCount'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.style.display = 'none';
    });
}

/* ========== DYNAMISCHE SPALTEN ========== */
function updateMasonryColumns() {
    const grid = document.getElementById('timeframeImagesGrid');
    if (!grid) return;
    
    const visibleItems = grid.querySelectorAll('.timeframe-image-item:not(.tf-hidden)');
    const count = visibleItems.length;
    
    const w = window.innerWidth;
    let maxCols = 6;
    if (w <= 480) maxCols = 2;
    else if (w <= 768) maxCols = 3;
    else if (w <= 900) maxCols = 3;
    else if (w <= 1100) maxCols = 4;
    else if (w <= 1400) maxCols = 5;
    
    const cols = Math.max(1, Math.min(maxCols, count));
    grid.style.columnCount = cols;
}

// Bei Resize auch Spalten neu berechnen
window.addEventListener('resize', updateMasonryColumns);

/* ========== PAKET-AUSWAHL ========== */
function toggleTimeframeImageSelection(tfItem) {
    if (typeof toggleImageSelection !== 'function') return;
    
    const imageId = tfItem.dataset.imageId;
    
    // Prüfe ob Hauptgalerie-Card existiert — wenn ja, nutze die
    const mainCard = document.querySelector(`.speedshot-image-card[data-image-id="${imageId}"], .speedshot-grid-card[data-image-id="${imageId}"]`);
    
    if (mainCard) {
        toggleImageSelection(mainCard);
    } else {
        // Kein Card in der Galerie sichtbar → nutze Timeframe-Item direkt
        toggleImageSelection(tfItem);
    }
    
    // UI im Timeframe-Modal aktualisieren
    const isNowSelected = typeof PackageSelectionState !== 'undefined' 
        && PackageSelectionState.selectedImages 
        && PackageSelectionState.selectedImages.has(String(imageId));
    
    // Toggle Klasse
    tfItem.classList.toggle('image-selected', isNowSelected);
    
    // btn-package aktualisieren
    const btn = tfItem.querySelector('.btn-package');
    if (btn) {
        btn.classList.toggle('is-selected', isNowSelected);
        btn.title = isNowSelected ? 'Aus Paket entfernen' : 'Zum Paket hinzufügen';
        btn.innerHTML = isNowSelected
            ? '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"/></svg>'
            : '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><line x1="12" y1="8" x2="12" y2="16"/><line x1="8" y1="12" x2="16" y2="12"/></svg>';
    }
    
    // btn-shop im Timeframe-Modal ein-/ausblenden
    const tfShopBtn = tfItem.querySelector('.btn-shop');
    if (tfShopBtn && !tfShopBtn.classList.contains('in-cart')) {
        tfShopBtn.style.display = isNowSelected ? 'none' : '';
    }
    
    // Auch Hauptgalerie-Card synchronisieren (falls vorhanden)
    if (mainCard) {
        mainCard.classList.toggle('image-selected', isNowSelected);
    }
}

// ESC-Taste schließt Modal
document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
        closeTimeframeModal();
    }
});

/* ========== HOVER PREVIEW IM MODAL ========== */
let tfPreviewTimeout = null;

function tfShowPreview(imageSrc) {
    if (!imageSrc) return;
    
    clearTimeout(tfPreviewTimeout);
    
    const preview = document.getElementById('imageHoverPreview');
    const img = document.getElementById('imageHoverPreviewImg');
    
    if (preview && img) {
        // z-index über Modal setzen
        preview.style.zIndex = '10001';
        img.src = imageSrc;
        preview.classList.add('visible');
    }
}

function tfHidePreview() {
    clearTimeout(tfPreviewTimeout);
    
    const preview = document.getElementById('imageHoverPreview');
    if (preview) {
        preview.classList.remove('visible');
    }
}
</script>

