<!-- ═══════════════════════════════════════════════════════
     STYLES
═══════════════════════════════════════════════════════ -->
<style>
/* ── VARIABLES ───────────────────────────────────────── */
:root {
    --af-green: #9dd337;
    --af-green-d: #7ab82d;
    --af-dark: #111;
    --af-mid: #666;
    --af-border: #e0e0dc;
    --af-bg: #f8f8f6;
    --af-radius: 12px;
    --af-shadow: 0 8px 32px rgba(0,0,0,.14);
}

/* ── FAB ─────────────────────────────────────────────── */
.af-fab {
    position: fixed;
    bottom: 24px;
    right: 24px;
    z-index: 9990;
    background: var(--af-dark);
    color: #fff;
    border: none;
    padding: 11px 18px;
    border-radius: 100px;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 8px;
    box-shadow: 0 4px 20px rgba(0,0,0,.25);
    font-family: inherit;
    transition: transform .15s, background .15s;
    animation: afPulse 3s infinite;
}
@keyframes afPulse {
    0%,100% { box-shadow: 0 4px 20px rgba(0,0,0,.25); }
    50%      { box-shadow: 0 4px 28px rgba(157,211,55,.45); }
}
.af-fab:hover { background: #222; transform: translateY(-2px); animation: none; }
.af-fab.hidden { display: none; }
.af-fab-dot {
    width: 7px; height: 7px;
    background: var(--af-green);
    border-radius: 50%;
    animation: afBlink 1.8s infinite;
}
@keyframes afBlink { 0%,100%{opacity:1} 50%{opacity:.2} }

/* ── MODAL OVERLAY ───────────────────────────────────── */
.af-modal-overlay {
    position: fixed; inset: 0;
    background: rgba(0,0,0,.6);
    backdrop-filter: blur(4px);
    z-index: 9995;
    opacity: 0; pointer-events: none;
    transition: opacity .25s;
}
.af-modal-overlay.open { opacity: 1; pointer-events: auto; }

/* ── WIZARD MODAL ────────────────────────────────────── */
.af-modal {
    position: fixed;
    top: 50%; left: 50%;
    transform: translate(-50%, -44%) scale(.96);
    z-index: 9996;
    width: min(500px, 96vw);
    background: #fff;
    border-radius: 20px;
    box-shadow: 0 24px 64px rgba(0,0,0,.2);
    opacity: 0; pointer-events: none;
    transition: opacity .25s, transform .25s cubic-bezier(.17,.67,.35,1.05);
    overflow: hidden;
}
.af-modal.open {
    opacity: 1; pointer-events: auto;
    transform: translate(-50%, -50%) scale(1);
}
@media (max-width: 600px) {
    .af-modal {
        top: auto; bottom: 0; left: 0;
        transform: translateY(20px);
        width: 100vw; border-radius: 20px 20px 0 0;
    }
    .af-modal.open { transform: translateY(0); }
}

.af-modal-close {
    position: absolute; top: 14px; right: 14px;
    background: rgba(0,0,0,.06); border: none;
    width: 32px; height: 32px; border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    cursor: pointer; color: var(--af-mid);
    transition: background .15s; z-index: 2;
}
.af-modal-close:hover { background: rgba(0,0,0,.12); color: var(--af-dark); }

.af-modal-header {
    display: flex; align-items: center; gap: 14px;
    padding: 24px 24px 0;
}
.af-modal-icon {
    width: 46px; height: 46px;
    background: linear-gradient(135deg, var(--af-green), var(--af-green-d));
    border-radius: 13px;
    display: flex; align-items: center; justify-content: center;
    flex-shrink: 0; color: #fff;
}
.af-modal-title { font-size: 18px; font-weight: 700; color: var(--af-dark); }
.af-modal-subtitle { font-size: 12px; color: var(--af-mid); margin-top: 2px; }

/* Steps */
.af-steps {
    display: flex; align-items: flex-start;
    padding: 20px 24px 4px;
    position: relative;
}
.af-steps-line {
    position: absolute;
    top: calc(20px + 16px);
    left: calc(24px + 20px);
    right: calc(24px + 20px);
    height: 2px;
    background: var(--af-border);
    z-index: 0;
}
.af-step {
    flex: 1; display: flex; flex-direction: column;
    align-items: center; gap: 5px; position: relative; z-index: 1;
}
.af-step-dot {
    width: 32px; height: 32px; border-radius: 50%;
    border: 2px solid var(--af-border);
    background: #fff;
    display: flex; align-items: center; justify-content: center;
    font-size: 12px; font-weight: 700; color: #bbb;
    transition: all .2s;
}
.af-step.active .af-step-dot { border-color: var(--af-dark); background: var(--af-dark); color: #fff; }
.af-step.done .af-step-dot   { border-color: var(--af-green); background: var(--af-green); color: #fff; }
.af-step-label { font-size: 11px; font-weight: 500; color: #bbb; }
.af-step.active .af-step-label { color: var(--af-dark); font-weight: 600; }
.af-step.done .af-step-label   { color: var(--af-green-d); }

/* Step bodies */
.af-step-body { padding: 16px 24px 8px; min-height: 140px; }
.af-field-label {
    font-size: 11px; font-weight: 700;
    text-transform: uppercase; letter-spacing: .07em;
    color: var(--af-mid); margin-bottom: 6px;
}
.af-field-hint { font-size: 12px; color: #aaa; margin-bottom: 8px; }

/* Tag input */
.af-tag-wrap {
    border: 1.5px solid var(--af-border);
    border-radius: 10px; padding: 7px 10px;
    display: flex; flex-wrap: wrap; gap: 6px;
    align-items: center; min-height: 44px;
    cursor: text; transition: border-color .2s; background: #fff;
}
.af-tag-wrap:focus-within { border-color: var(--af-dark); }
.af-tag {
    background: var(--af-dark); color: #fff;
    font-size: 13px; font-weight: 600;
    padding: 3px 10px; border-radius: 6px;
    display: flex; align-items: center; gap: 5px;
    font-family: 'DM Mono', monospace, sans-serif;
    white-space: nowrap;
}
.af-tag-x {
    cursor: pointer; opacity: .6;
    font-size: 14px; line-height: 1; font-family: sans-serif;
}
.af-tag-x:hover { opacity: 1; }
.af-tag-input {
    border: none; outline: none;
    font-size: 14px; min-width: 60px;
    background: transparent; color: var(--af-dark);
    font-family: inherit;
}

/* Time entries */
.af-time-entry {
    display: flex; align-items: center; gap: 8px;
    border: 1.5px solid var(--af-border); border-radius: 10px;
    padding: 8px 12px; background: #fff; margin-bottom: 7px;
    transition: border-color .2s;
}
.af-time-entry:focus-within { border-color: var(--af-dark); }
.af-time-input {
    flex: 1; border: none; outline: none;
    font-size: 16px; font-weight: 500;
    color: var(--af-dark); background: transparent;
    font-family: inherit;
}
.af-time-wave {
    font-size: 11px; font-weight: 600;
    background: var(--af-bg); color: var(--af-mid);
    padding: 2px 7px; border-radius: 5px; white-space: nowrap;
}
.af-time-del {
    background: none; border: none; cursor: pointer;
    color: #ccc; padding: 3px; line-height: 1;
    display: flex; transition: color .15s;
}
.af-time-del:hover { color: #e55; }
.af-add-time-btn {
    border: 1.5px dashed var(--af-border);
    border-radius: 9px; padding: 8px 12px;
    font-size: 12px; color: var(--af-mid);
    background: none; cursor: pointer;
    font-family: inherit; width: 100%;
    display: flex; align-items: center; gap: 6px;
    transition: border-color .15s, color .15s;
}
.af-add-time-btn:hover { border-color: var(--af-dark); color: var(--af-dark); }

/* Tolerance */
.af-tolerance-row {
    display: flex; align-items: center; gap: 10px; margin-top: 14px;
}
.af-tol-label { font-size: 12px; color: var(--af-mid); flex-shrink: 0; }
input[type="range"].af-tol { flex: 1; accent-color: var(--af-green); }
#afTolSlider, #afPanelTolSlider { flex: 1; accent-color: var(--af-green); }
.af-tol-val { font-size: 13px; font-weight: 600; color: var(--af-dark); min-width: 50px; text-align: right; }

/* Result step */
.af-result-box {
    background: var(--af-bg); border-radius: 12px; padding: 20px;
    min-height: 120px; display: flex; align-items: center; justify-content: center;
}
.af-result-loading { display: flex; align-items: center; gap: 10px; color: var(--af-mid); font-size: 14px; }
.af-spinner {
    width: 20px; height: 20px;
    border: 2.5px solid var(--af-border);
    border-top-color: var(--af-green);
    border-radius: 50%;
    animation: afSpin .7s linear infinite;
}
@keyframes afSpin { to { transform: rotate(360deg); } }
.af-result-found { text-align: center; width: 100%; }
.af-result-count { font-size: 48px; font-weight: 800; color: var(--af-green-d); line-height: 1; }
.af-result-label { font-size: 14px; color: var(--af-mid); margin: 4px 0 12px; }
.af-result-detail { font-size: 11px; color: #aaa; margin-bottom: 12px; }
.af-result-thumbs { display: flex; gap: 6px; justify-content: center; flex-wrap: wrap; }
.af-result-thumb {
    width: 52px; height: 52px; border-radius: 8px;
    background: #ddd; object-fit: cover;
}
.af-result-thumb-more {
    width: 52px; height: 52px; border-radius: 8px;
    background: var(--af-dark); color: #fff;
    font-size: 13px; font-weight: 700;
    display: flex; align-items: center; justify-content: center;
}
.af-result-empty { text-align: center; color: var(--af-mid); }

/* Footer */
.af-modal-footer {
    display: flex; gap: 10px;
    padding: 12px 24px 24px; align-items: center;
}
.af-btn-back {
    background: none; border: 1.5px solid var(--af-border);
    padding: 10px 18px; border-radius: 9px;
    font-size: 14px; font-weight: 500; cursor: pointer;
    font-family: inherit; color: var(--af-mid);
    transition: all .15s; flex-shrink: 0;
}
.af-btn-back:hover { border-color: var(--af-dark); color: var(--af-dark); }
.af-btn-next {
    flex: 1; background: var(--af-dark); color: #fff;
    border: none; padding: 11px 20px; border-radius: 9px;
    font-size: 14px; font-weight: 700; cursor: pointer;
    font-family: inherit;
    display: flex; align-items: center; justify-content: center; gap: 8px;
    transition: background .15s, transform .1s;
}
.af-btn-next:hover { background: #222; transform: translateY(-1px); }
.af-btn-next.af-green { background: var(--af-green); color: #fff; }
.af-btn-next.af-green:hover { background: var(--af-green-d); }
.af-btn-next:disabled { opacity: .5; cursor: not-allowed; transform: none; }

/* ── FLOATING PANEL ──────────────────────────────────── */
.af-panel {
    position: fixed;
    top: 50%;
    right: 0;
    transform: translateY(-50%) translateX(0);
    z-index: 9990;
    width: 280px;
    background: #fff;
    border-radius: 16px 0 0 16px;
    box-shadow: -6px 0 32px rgba(0,0,0,.12);
    display: flex; flex-direction: column;
    transition: transform .3s cubic-bezier(.4,0,.2,1), opacity .3s;
    max-height: 90vh;
    overflow: hidden;
}
.af-panel.closed {
    transform: translateY(-50%) translateX(100%);
    opacity: 0;
    pointer-events: none;
}
.af-panel-header {
    padding: 12px 14px;
    border-bottom: 1px solid var(--af-border);
    display: flex; align-items: center; justify-content: space-between;
    flex-shrink: 0;
}
.af-panel-header-left { display: flex; align-items: center; gap: 8px; }
.af-panel-icon {
    width: 28px; height: 28px;
    background: var(--af-dark); border-radius: 7px;
    display: flex; align-items: center; justify-content: center; color: #fff;
}
.af-panel-title { font-size: 13px; font-weight: 700; color: var(--af-dark); }
.af-panel-icon-btn {
    background: none; border: none; cursor: pointer;
    color: #bbb; padding: 4px; border-radius: 5px;
    display: flex; transition: color .15s;
}
.af-panel-icon-btn:hover { color: var(--af-dark); background: var(--af-bg); }

.af-panel-body {
    flex: 1; overflow-y: auto;
    padding: 12px 14px;
    display: flex; flex-direction: column; gap: 12px;
    -webkit-overflow-scrolling: touch;
}
.af-p-section {}
.af-p-label {
    font-size: 10px; font-weight: 700;
    text-transform: uppercase; letter-spacing: .08em;
    color: var(--af-mid); margin-bottom: 5px;
}
.af-panel-tags { padding: 5px 8px; min-height: 36px; }
.af-p-tolerance {
    display: flex; align-items: center; gap: 8px;
    background: var(--af-bg); border-radius: 8px; padding: 7px 10px;
}
.af-p-result {
    background: linear-gradient(135deg, var(--af-dark), #2a2a2a);
    border-radius: 10px; padding: 12px;
    display: flex; align-items: center; gap: 10px;
}
.af-p-result-num {
    font-size: 28px; font-weight: 800;
    color: var(--af-green); line-height: 1;
    font-family: 'DM Mono', monospace, sans-serif;
}
.af-p-result-txt { font-size: 11px; color: rgba(255,255,255,.55); margin-top: 2px; }

.af-panel-footer {
    padding: 10px 14px 14px;
    border-top: 1px solid var(--af-border);
    flex-shrink: 0;
    padding-bottom: max(14px, env(safe-area-inset-bottom, 14px));
}
.af-p-search-btn {
    width: 100%; background: var(--af-green); color: #fff;
    border: none; padding: 10px; border-radius: 9px;
    font-size: 13px; font-weight: 700; cursor: pointer;
    font-family: inherit;
    display: flex; align-items: center; justify-content: center; gap: 7px;
    transition: background .15s, transform .1s;
}
.af-p-search-btn:hover { background: var(--af-green-d); transform: translateY(-1px); }
.af-p-search-btn:disabled { opacity: .5; cursor: not-allowed; transform: none; }
.af-p-reset-btn {
    width: 100%; background: none; border: none;
    padding: 7px; font-size: 12px; color: #bbb;
    cursor: pointer; font-family: inherit; margin-top: 5px;
    transition: color .15s;
}
.af-p-reset-btn:hover { color: var(--af-mid); }

/* Active filter indicator in gallery */
.af-filter-active-bar {
    background: linear-gradient(135deg, #f0fad8, #e6f5c0);
    border: 1.5px solid var(--af-green);
    border-radius: 10px;
    padding: 8px 14px;
    margin: 0 0 12px;
    display: flex; align-items: center; gap: 10px;
    font-size: 13px; color: #4a7a10;
    display: none;
}
.af-filter-active-bar.visible { display: flex; }
.af-filter-active-bar strong { font-weight: 700; }
.af-filter-reset {
    margin-left: auto; background: none; border: none;
    color: #4a7a10; font-size: 12px; cursor: pointer;
    font-family: inherit; font-weight: 600; padding: 0;
    text-decoration: underline;
}

@media (max-width: 768px) {
    .af-fab { display: none !important; }
    .af-panel {
        top: auto; bottom: 0; right: 0;
        transform: translateY(0);
        width: 100vw; max-height: 70vh;
        border-radius: 20px 20px 0 0;
    }
    .af-panel.closed { transform: translateY(100%); }
}
</style>

<!-- ═══════════════════════════════════════════════════════
     JAVASCRIPT
═══════════════════════════════════════════════════════ -->
<script>
(function() {
    'use strict';

    // ── State ─────────────────────────────────────────────
    var AF = {
        wizardStep: 1,
        bib:   [],       // Startnummern
        times: [],       // Startzeiten [{time:'09:42'}]
        tolerance: 15,   // Minuten
        panelOpen: false,
        lastResults: null,
        searchTimer: null,
        eventId: 846,
        ajaxUrl: 'https://speedshot.net/wp-admin/admin-ajax.php',
        nonce: '25a9efb3cc'
    };

    // ── Wizard open/close ─────────────────────────────────
    window.afOpenModal = function() {
        var overlay = document.getElementById('afModalOverlay');
        var modal   = document.getElementById('afModal');
        var fab     = document.getElementById('afFab');
        if (!modal) return;
        if (overlay) overlay.classList.add('open');
        modal.classList.add('open');
        if (fab) fab.classList.add('hidden');
        afClosePanel();
        if (AF.wizardStep > 1 && AF.bib.length === 0) {
            AF.wizardStep = 1;
            afRenderWizard();
        }
    };
    window.afCloseModal = function() {
        var overlay = document.getElementById('afModalOverlay');
        var modal   = document.getElementById('afModal');
        var fab     = document.getElementById('afFab');
        if (overlay) overlay.classList.remove('open');
        if (modal)   modal.classList.remove('open');
        if (fab)     fab.classList.remove('hidden');
    };

    // ── Panel open/close ──────────────────────────────────
    window.afOpenPanel = function() {
        var panel = document.getElementById('afPanel');
        var fab   = document.getElementById('afFab');
        if (!panel) return;
        AF.panelOpen = true;
        panel.classList.remove('closed');
        if (fab) fab.classList.add('hidden');
        afRenderPanelTimes();
    };
    window.afClosePanel = function() {
        var panel = document.getElementById('afPanel');
        var fab   = document.getElementById('afFab');
        if (!panel) return;
        AF.panelOpen = false;
        panel.classList.add('closed');
        var modal = document.getElementById('afModal');
        if (fab && (!modal || !modal.classList.contains('open'))) {
            fab.classList.remove('hidden');
        }
    };

    // ── Bib number handling ───────────────────────────────
    function renderBibTags(wrapId, inputId) {
        var wrap = document.getElementById(wrapId);
        var input = document.getElementById(inputId);
        // Remove old tags
        wrap.querySelectorAll('.af-tag').forEach(function(t) { t.remove(); });
        AF.bib.forEach(function(num) {
            var tag = document.createElement('div');
            tag.className = 'af-tag';
            tag.innerHTML = '# ' + num + ' <span class="af-tag-x" data-bib="' + num + '">×</span>';
            tag.querySelector('.af-tag-x').onclick = function() {
                AF.bib = AF.bib.filter(function(b){ return b !== num; });
                renderAllBibTags();
                afPanelSearch();
            };
            wrap.insertBefore(tag, input);
        });
    }
    function renderAllBibTags() {
        renderBibTags('afNumWrap', 'afNumInput');
        renderBibTags('afPanelNumWrap', 'afPanelNumInput');
    }

    function afAddBib(val) {
        val = val.trim().replace(/[^0-9,;\s]+/g, '').trim();
        var nums = val.split(/[,;\s]+/).filter(function(v){ return v.length > 0; });
        nums.forEach(function(n) {
            if (n && !AF.bib.includes(n)) AF.bib.push(n);
        });
        renderAllBibTags();
    }

    window.afHandleNumKey = function(e) {
        var input = document.getElementById('afNumInput');
        if ((e.key === 'Enter' || e.key === ',' || e.key === ' ') && input.value.trim()) {
            e.preventDefault();
            afAddBib(input.value);
            input.value = '';
        }
    };
    window.afHandleNumKeyPanel = function(e) {
        var input = document.getElementById('afPanelNumInput');
        if ((e.key === 'Enter' || e.key === ',' || e.key === ' ') && input.value.trim()) {
            e.preventDefault();
            afAddBib(input.value);
            input.value = '';
            afPanelSearch();
        }
    };
    window.afNumInputResize = function(el) {
        el.style.width = Math.max(60, el.value.length * 10 + 20) + 'px';
    };

    // ── Time entries ──────────────────────────────────────
    function renderTimes(listId, context) {
        var list = document.getElementById(listId);
        list.innerHTML = '';
        if (AF.times.length === 0) {
            list.innerHTML = '<div style="font-size:12px;color:#bbb;padding:6px 0">Noch keine Startzeit eingetragen</div>';
            return;
        }
        AF.times.forEach(function(t, i) {
            var div = document.createElement('div');
            div.className = 'af-time-entry';
            div.innerHTML =
                '<svg style="color:#bbb;flex-shrink:0" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>' +
                '<input class="af-time-input" type="time" value="' + t.time + '" data-idx="' + i + '">' +
                '<span class="af-time-wave">Welle ' + (i+1) + '</span>' +
                '<button class="af-time-del" data-idx="' + i + '" title="Entfernen">' +
                    '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>' +
                '</button>';
            list.appendChild(div);
        });
        list.querySelectorAll('.af-time-input').forEach(function(inp) {
            inp.onchange = function() {
                AF.times[parseInt(this.dataset.idx)].time = this.value;
                if (context === 'panel') afPanelSearch();
            };
        });
        list.querySelectorAll('.af-time-del').forEach(function(btn) {
            btn.onclick = function() {
                AF.times.splice(parseInt(this.dataset.idx), 1);
                renderTimes(listId, context);
                if (context === 'panel') afPanelSearch();
            };
        });
    }
    window.afAddTime = function() {
        var now = new Date();
        var h = String(now.getHours()).padStart(2,'0');
        var m = String(now.getMinutes()).padStart(2,'0');
        AF.times.push({ time: h + ':' + m });
        renderTimes('afTimeList', 'wizard');
    };
    window.afAddTimePanel = function() {
        var now = new Date();
        var h = String(now.getHours()).padStart(2,'0');
        var m = String(now.getMinutes()).padStart(2,'0');
        AF.times.push({ time: h + ':' + m });
        renderTimes('afPanelTimeList', 'panel');
        afPanelSearch();
    };
    window.afRenderPanelTimes = function() {
        renderTimes('afPanelTimeList', 'panel');
    };

    // ── Wizard navigation ─────────────────────────────────
    window.afWizardNext = function() {
        if (AF.wizardStep === 1) {
            // Flush text input
            var inp = document.getElementById('afNumInput');
            if (inp.value.trim()) { afAddBib(inp.value); inp.value = ''; }
            // Startnummer ist optional – kein Pflichtfeld
        }
        if (AF.wizardStep === 2) {
            if (AF.times.length === 0) {
                document.getElementById('afBody2').querySelector('.af-add-time-btn').style.borderColor = '#e55';
                setTimeout(function(){ document.getElementById('afBody2').querySelector('.af-add-time-btn').style.borderColor = ''; }, 1500);
                return;
            }
            AF.tolerance = parseInt(document.getElementById('afTolSlider').value);
        }
        if (AF.wizardStep < 3) {
            AF.wizardStep++;
            afRenderWizard();
            if (AF.wizardStep === 3) afRunSearch('wizard');
        } else {
            // Apply filter and close
            if (AF.lastResults && AF.lastResults.image_ids) {
                afApplyFilter();
            }
            afCloseModal();
        }
    };
    window.afWizardBack = function() {
        if (AF.wizardStep > 1) {
            AF.wizardStep--;
            afRenderWizard();
        }
    };

    function afRenderWizard() {
        // Bodies
        [1,2,3].forEach(function(i) {
            document.getElementById('afBody'+i).style.display = i === AF.wizardStep ? '' : 'none';
        });
        // Dots
        [1,2,3].forEach(function(i) {
            var dot = document.getElementById('afDot'+i);
            dot.className = 'af-step' + (i < AF.wizardStep ? ' done' : (i === AF.wizardStep ? ' active' : ''));
            dot.querySelector('span').textContent = i < AF.wizardStep ? '✓' : i;
        });
        // Buttons
        var back = document.getElementById('afBtnBack');
        var next = document.getElementById('afBtnNext');
        back.style.display = AF.wizardStep > 1 ? '' : 'none';
        if (AF.wizardStep === 3) {
            next.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg> Galerie filtern';
            next.className = 'af-btn-next af-green';
        } else if (AF.wizardStep === 2) {
            next.innerHTML = 'Suchen <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="9 18 15 12 9 6"/></svg>';
            next.className = 'af-btn-next';
        } else {
            next.innerHTML = 'Weiter: Startzeit <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="9 18 15 12 9 6"/></svg>';
            next.className = 'af-btn-next';
        }
        // Sync time list
        if (AF.wizardStep === 2) renderTimes('afTimeList', 'wizard');
    }

    // ── AJAX Search ───────────────────────────────────────
    function afRunSearch(context) {
        var loadEl   = document.getElementById('afResultLoading');
        var foundEl  = document.getElementById('afResultFound');
        var emptyEl  = document.getElementById('afResultEmpty');
        if (loadEl)  { loadEl.style.display = ''; foundEl.style.display = 'none'; emptyEl.style.display = 'none'; }

        clearTimeout(AF.searchTimer);
        AF.searchTimer = setTimeout(function() {
            fetch(AF.ajaxUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: new URLSearchParams({
                    action:    'speedshot_athlete_search',
                    nonce:     AF.nonce,
                    event_id:  AF.eventId,
                    bib:       JSON.stringify(AF.bib),
                    times:     JSON.stringify(AF.times.map(function(t){ return t.time; })),
                    tolerance: AF.tolerance
                })
            })
            .then(function(r){ return r.json(); })
            .then(function(data) {
                if (!data.success) throw new Error(data.data || 'Fehler');
                AF.lastResults = data.data;
                if (context === 'wizard') afShowWizardResult(data.data);
                if (context === 'panel') {
                    afShowPanelResult(data.data);
                    // Direkt filtern wenn Button geklickt wurde
                    if (AF._applyAfterSearch) {
                        AF._applyAfterSearch = false;
                        afApplyFilter();
                    }
                }
            })
            .catch(function(err) {
                console.error('[AF] Search error:', err);
                if (loadEl) { loadEl.style.display = 'none'; emptyEl.style.display = ''; }
            });
        }, context === 'panel' ? 600 : 0);
    }

    function afShowWizardResult(data) {
        var loadEl  = document.getElementById('afResultLoading');
        var foundEl = document.getElementById('afResultFound');
        var emptyEl = document.getElementById('afResultEmpty');
        loadEl.style.display = 'none';

        var count = data.count || 0;
        if (count === 0) { emptyEl.style.display = ''; return; }
        foundEl.style.display = '';
        document.getElementById('afResultCount').textContent = count;
        var detail = 'Nr. ' + AF.bib.join(', ');
        if (AF.times.length > 0) detail += ' · ' + AF.times.map(function(t){ return t.time; }).join(', ') + ' ±' + AF.tolerance + ' Min';
        document.getElementById('afResultDetail').textContent = detail;

        // Thumbnails
        var thumbsEl = document.getElementById('afResultThumbs');
        thumbsEl.innerHTML = '';
        var show = Math.min(4, (data.thumbnails || []).length);
        for (var i = 0; i < show; i++) {
            var img = document.createElement('img');
            img.className = 'af-result-thumb';
            img.src = data.thumbnails[i];
            img.alt = '';
            thumbsEl.appendChild(img);
        }
        if (count > show) {
            var more = document.createElement('div');
            more.className = 'af-result-thumb-more';
            more.textContent = '+' + (count - show);
            thumbsEl.appendChild(more);
        }
        // Update next btn
        document.getElementById('afBtnNext').textContent = count + ' Bilder anzeigen ✓';
    }

    function afShowPanelResult(data) {
        var resultEl = document.getElementById('afPanelResult');
        var count = data.count || 0;
        document.getElementById('afPanelResultNum').textContent = count;
        resultEl.style.display = count > 0 ? '' : 'none';
        var btnTxt = count > 0 ? count + ' Bilder anzeigen' : 'Keine Treffer';
        document.getElementById('afPanelBtnTxt').textContent = btnTxt;
    }

    window.afPanelSearch = function() {
        if (AF.times.length === 0) return;
        AF.tolerance = parseInt(document.getElementById('afPanelTolSlider').value);
        afRunSearch('panel');
    };

    // ── Apply filter: URL-Parameter setzen → Seite neu laden ─────────────
    function afApplyFilter() {
        if (!AF.lastResults || !AF.lastResults.image_ids) return;

        var url = new URL(window.location.href);

        // Athlete-Finder Parameter setzen
        var bib = AF.bib.join(',');
        var times = AF.times.map(function(t){ return t.time; }).join(',');

        if (bib)   url.searchParams.set('af_bib',   bib);
        else       url.searchParams.delete('af_bib');

        url.searchParams.set('af_times', times);
        url.searchParams.set('af_tol',   AF.tolerance);

        // Zurück zu Seite 1
        url.searchParams.set('pg', '1');

        window.location.href = url.toString();
    }

    window.afPanelApply = function() {
        if (AF.times.length === 0) {
            var lbl = document.querySelector('#afPanelTimeList').previousElementSibling;
            if (lbl) { lbl.style.color = '#e55'; setTimeout(function(){ lbl.style.color = ''; }, 1500); }
            return;
        }
        AF.tolerance = parseInt(document.getElementById('afPanelTolSlider').value);
        AF._applyAfterSearch = true;
        afRunSearch('panel');
    };

    function afReset() {
        var url = new URL(window.location.href);
        url.searchParams.delete('af_bib');
        url.searchParams.delete('af_times');
        url.searchParams.delete('af_tol');
        url.searchParams.set('pg', '1');
        window.location.href = url.toString();
    }
    window.afPanelReset = afReset;

    // ── Init ──────────────────────────────────────────────
    document.addEventListener('DOMContentLoaded', function() {

        // State aus URL-Parametern wiederherstellen
        var urlParams = new URLSearchParams(window.location.search);
        var afBibUrl   = urlParams.get('af_bib');
        var afTimesUrl = urlParams.get('af_times');
        var afTolUrl   = urlParams.get('af_tol');

        if (afBibUrl) {
            afBibUrl.split(',').forEach(function(b) {
                if (b.trim()) AF.bib.push(b.trim());
            });
        }
        if (afTimesUrl) {
            afTimesUrl.split(',').forEach(function(t) {
                if (t.trim()) AF.times.push({ time: t.trim() });
            });
        }
        if (afTolUrl) {
            AF.tolerance = parseInt(afTolUrl);
            document.getElementById('afTolSlider').value = AF.tolerance;
            document.getElementById('afPanelTolSlider').value = AF.tolerance;
            document.getElementById('afTolVal').textContent = AF.tolerance + ' Min';
            document.getElementById('afPanelTolVal').textContent = AF.tolerance + ' Min';
        }

        // UI vorbelegen wenn Filter aktiv
        if (AF.times.length > 0) {
            renderAllBibTags();
            renderTimes('afTimeList', 'wizard');
            renderTimes('afPanelTimeList', 'panel');

            // Filter-Bar anzeigen
            var totalCount = 187;
            var bar = document.getElementById('afFilterActiveBar');
            if (bar) {
                bar.classList.add('visible');
                var info = totalCount + ' Bilder';
                if (AF.bib.length > 0) info += ' · Nr. ' + AF.bib.join(', ');
                info += ' · ' + AF.times.map(function(t){ return t.time; }).join(', ') + ' ±' + AF.tolerance + ' Min';
                bar.querySelector('.af-filter-info').textContent = info;
            }

            // Panel: Reset-Button zeigen, Ergebnis zeigen
            document.getElementById('afPanelResetBtn').style.display = '';
            document.getElementById('afPanelResultNum').textContent = totalCount;
            document.getElementById('afPanelResult').style.display = '';
            document.getElementById('afPanelBtnTxt').textContent = totalCount + ' Bilder anzeigen';

            // Panel öffnen
            afOpenPanel();
        }

        // Schließen per Esc
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape') { afCloseModal(); afClosePanel(); }
        });

        // Panel initial geschlossen wenn kein Filter aktiv
        if (AF.times.length === 0) {
            document.getElementById('afPanel').classList.add('closed');
        }
    });

})();
</script>

