<!-- Shop Integration Script -->
<script>
// Add Image to Shop Cart - NUR Aufruf, Shop macht ALLES
function addImageToShopCart(imageData) {
    if (typeof SpeedShot_Shop_AddToCart === 'undefined') {
        console.error('Shop-Plugin nicht installiert!');
        return;
    }
    
    // Zeige Loading am Button
    const btn = event.target;
    const originalText = btn.innerHTML;
    btn.innerHTML = '⏳';
    btn.disabled = true;
    
    // INTELLIGENTE PAKET-LOGIK
    // Prüfe ob ein Paket ausgewählt ist
    if (typeof PackageSelectionState !== 'undefined' && PackageSelectionState.selectedPackage) {
        const package = PackageSelectionState.selectedPackage;
        const currentCount = PackageSelectionState.selectedImages.size;
        const maxImages = PackageSelectionState.maxImages;
        const includesAll = PackageSelectionState.includesAllMedia;
        
        console.log('📦 Paket aktiv:', package.name, '- Bilder:', currentCount, '/', maxImages);
        
        // Prüfe ob Paket voll ist
        if (!includesAll && currentCount >= maxImages) {
            btn.innerHTML = originalText;
            btn.disabled = false;
            
            // Zeige Upgrade-Modal
            showPackageUpgradeModal(imageData, package, currentCount, maxImages);
            return;
        }
        
        // Finde die Card für dieses Bild
        const card = document.querySelector(`[data-image-id="${imageData.id}"]`);
        if (!card) {
            console.error('[PACKAGE] Card not found for image:', imageData.id);
            btn.innerHTML = originalText;
            btn.disabled = false;
            return;
        }
        
        // Füge zum Paket hinzu (verwende die toggleImageSelection Funktion)
        if (typeof window.toggleImageSelection === 'function') {
            window.toggleImageSelection(card);  // ← Card übergeben, nicht ID!
            
            // Button wurde bereits in toggleImageSelection versteckt
            return;
        }
    }
    
    // NORMALER WARENKORB-FLOW (kein Paket ausgewählt)
    const data = {
        image_id: imageData.id,
        title: imageData.title,
        price: parseFloat(imageData.price),
        thumbnail_url: imageData.thumbnail
    };
    
    SpeedShot_Shop_AddToCart('image', data)
        .then(result => {
            if (result) {
                // Verstecke den Button komplett
                btn.style.display = 'none';
                
                const card = btn.closest('.speedshot-grid-card, .speedshot-image-card');
                if (card) {
                    card.setAttribute('data-in-cart', '1');
                }
            }
        })
        .catch(err => {
            console.error('Cart error:', err);
            btn.innerHTML = originalText;
            btn.disabled = false;
        });
}

// Modal für Package-Upgrade wenn Paket voll ist
function showPackageUpgradeModal(imageData, currentPackage, currentCount, maxImages) {
    const modalHTML = `
        <div class="package-upgrade-modal-overlay" onclick="closePackageUpgradeModal()">
            <div class="package-upgrade-modal-content" onclick="event.stopPropagation()">
                <h2 style="margin: 0 0 15px 0; color: #1a202c; display: flex; align-items: center; gap: 10px;">
                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#ed8936" stroke-width="2">
                        <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/>
                        <line x1="12" y1="9" x2="12" y2="13"/>
                        <line x1="12" y1="17" x2="12.01" y2="17"/>
                    </svg>
                    Paket ist voll
                </h2>
                <p style="margin: 0 0 20px 0; color: #4a5568; line-height: 1.6;">
                    Dein Paket <strong>"${currentPackage.name}"</strong> hat bereits <strong>${currentCount} von ${maxImages} Bildern</strong>.
                    <br><br>
                    Was möchtest du tun?
                </p>
                
                <div style="display: flex; flex-direction: column; gap: 12px;">
                    <button onclick="upgradePackageFromFull()" 
                            style="
                                padding: 14px 20px;
                                background: linear-gradient(135deg, #9dd337 0%, #7ab82d 100%);
                                color: white;
                                border: none;
                                border-radius: 8px;
                                font-size: 15px;
                                font-weight: 600;
                                cursor: pointer;
                                text-align: left;
                                transition: all 0.2s;
                            "
                            onmouseover="this.style.transform='translateX(5px)'"
                            onmouseout="this.style.transform='translateX(0)'">
                        <strong>↑ Auf größeres Paket upgraden</strong>
                        <div style="font-size: 13px; opacity: 0.9; margin-top: 4px;">
                            Wechsle zu einem Paket mit mehr Bildern
                        </div>
                    </button>
                    
                    <button onclick="addImageIndividuallyFromFull(${JSON.stringify(imageData).replace(/"/g, '&quot;')})" 
                            style="
                                padding: 14px 20px;
                                background: linear-gradient(135deg, #60a5fa 0%, #3b82f6 100%);
                                color: white;
                                border: none;
                                border-radius: 8px;
                                font-size: 15px;
                                font-weight: 600;
                                cursor: pointer;
                                text-align: left;
                                transition: all 0.2s;
                            "
                            onmouseover="this.style.transform='translateX(5px)'"
                            onmouseout="this.style.transform='translateX(0)'">
                        <strong>+ Einzeln zum Warenkorb hinzufügen</strong>
                        <div style="font-size: 13px; opacity: 0.9; margin-top: 4px;">
                            Dieses Bild separat kaufen (${imageData.price.toFixed(2)} €)
                        </div>
                    </button>
                    
                    <button onclick="closePackageUpgradeModal()" 
                            style="
                                padding: 14px 20px;
                                background: #e2e8f0;
                                color: #1a202c;
                                border: none;
                                border-radius: 8px;
                                font-size: 15px;
                                font-weight: 600;
                                cursor: pointer;
                                transition: all 0.2s;
                            "
                            onmouseover="this.style.background='#cbd5e0'"
                            onmouseout="this.style.background='#e2e8f0'">
                        Abbrechen
                    </button>
                </div>
            </div>
        </div>
        <style>
        .package-upgrade-modal-overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0, 0, 0, 0.7);
            display: flex;
            align-items: center;
            justify-content: center;
            z-index: 10002;
            animation: fadeIn 0.2s;
        }
        
        .package-upgrade-modal-content {
            background: white;
            padding: 30px;
            border-radius: 12px;
            max-width: 500px;
            width: 90%;
            box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
            animation: slideUp 0.3s;
        }
        </style>
    `;
    
    const modalDiv = document.createElement('div');
    modalDiv.id = 'package-upgrade-modal';
    modalDiv.innerHTML = modalHTML;
    document.body.appendChild(modalDiv);
}

function closePackageUpgradeModal() {
    const modal = document.getElementById('package-upgrade-modal');
    if (modal) modal.remove();
}

function upgradePackageFromFull() {
    closePackageUpgradeModal();
    if (typeof window.openPackageSelector === 'function') {
        window.openPackageSelector();
    }
}

function addImageIndividuallyFromFull(imageData) {
    closePackageUpgradeModal();
    
    const data = {
        image_id: imageData.id,
        title: imageData.title,
        price: parseFloat(imageData.price),
        thumbnail_url: imageData.thumbnail
    };
    
    SpeedShot_Shop_AddToCart('image', data)
        .then(result => {
            if (result) {
                console.log('✓ Bild einzeln zum Warenkorb hinzugefügt');
                
                // Verstecke den Button in der Card und btn-package
                const card = document.querySelector(`[data-image-id="${imageData.id}"]`);
                if (card) {
                    const shopBtn = card.querySelector('.btn-shop');
                    if (shopBtn) {
                        shopBtn.classList.add('in-cart');
                        shopBtn.disabled = true;
                        shopBtn.title = 'Im Warenkorb';
                        shopBtn.removeAttribute('onclick');
                        shopBtn.onclick = null;
                        shopBtn.innerHTML = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>';
                    }
                    const packageBtn = card.querySelector('.btn-package');
                    if (packageBtn) {
                        packageBtn.style.display = 'none';
                    }
                    card.setAttribute('data-in-cart', '1');
                }
            }
        })
        .catch(err => {
            console.error('Cart error:', err);
        });
}

</script>

