    .galerie-pagination .pagination-controls {
        gap: 6px;
    }
    
    .galerie-pagination .pagination-btn {
        padding: 6px 12px;
        font-size: 13px;
    }
}

/* ========================================================================
   LOADING SCREEN
   ======================================================================== */
.galerie-loading-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(255, 255, 255, 0.98);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 9999;
