    transition: width 0.3s ease;
}

/* ========================================================================
   COVER IMAGE HEADER
   ======================================================================== */
.galerie-cover-header {
    position: relative;
    width: 100%;
    height: 300px;
    overflow: hidden;
    margin-bottom: 20px;
    contain: layout;          /* Browser reserviert Platz sofort */
    background: #111;         /* Placeholder-Farbe bis Bild lädt */
}

.galerie-cover-header .cover-header-img {
    position: absolute;       /* Bild beeinflusst Containerhöhe NICHT */
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

/* Dezentes Gesamtabdunkeln – funktioniert auf hellen UND dunklen Bildern */
.galerie-cover-header::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.22);
    z-index: 1;
}

.galerie-cover-header .cover-header-overlay {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    padding: 100px 30px 22px;
    background: linear-gradient(
        to bottom,
        rgba(0, 0, 0, 0)    0%,
        rgba(0, 0, 0, 0.55) 55%,
        rgba(0, 0, 0, 0.88) 100%
    );
    color: white;
    z-index: 2;
}

.galerie-cover-header .cover-header-overlay h1 {
    margin: 0 0 8px;
    font-size: 32px;
    color: #fff;
    /* Mehrstufiger Halo – lesbar auf jedem Hintergrund */
    text-shadow:
        0 1px 2px rgba(0, 0, 0, 1),
        0 2px 6px rgba(0, 0, 0, 0.9),
        0 4px 16px rgba(0, 0, 0, 0.7);
}

.galerie-cover-header .cover-header-date {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 14px;
    opacity: 0.95;
    text-shadow: 0 1px 3px rgba(0, 0, 0, 0.9);
}

.galerie-header.has-cover-above .header-left h1 {
    display: none;
}

@media (max-width: 768px) {
    .galerie-cover-header {
        height: 200px;
        border-radius: 0;
        background: #111;
    }

    .galerie-cover-header .cover-header-overlay {
        padding: 60px 20px 20px;
    }

    .galerie-cover-header .cover-header-overlay h1 {
        font-size: 22px;
