/* Package Select Banner */
.package-select-banner {
    margin: 20px 0;
    display: flex;
    justify-content: center;
    padding: 15px;
    background: linear-gradient(135deg, rgba(157, 211, 55, 0.1) 0%, rgba(157, 211, 55, 0.05) 100%);
