    border: 2px dashed #9dd337;
}

.btn-select-package {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    padding: 14px 28px;
    background: linear-gradient(135deg, #9dd337 0%, #7ab82d 100%);
