    border: none;
    border-radius: 8px;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s;
    box-shadow: 0 4px 12px rgba(157, 211, 55, 0.3);
}

.btn-select-package:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(157, 211, 55, 0.4);
}

.btn-select-package svg {
    flex-shrink: 0;
}

.btn-select-package .package-count {
    padding: 4px 12px;
