.mfn-btn {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 3px;
    background: none;
    border: none;
    cursor: pointer;
    padding: 8px 4px 6px;
    font-family: inherit;
    color: #666;
    transition: color .15s, background .15s;
    -webkit-tap-highlight-color: transparent;
    position: relative;
}
.mfn-btn:active {
    background: rgba(0,0,0,0.04);
    color: #111;
}
.mfn-btn span {
    font-size: 10px;
    font-weight: 500;
    line-height: 1;
    white-space: nowrap;
}
.mfn-btn svg {
    flex-shrink: 0;
}
.mfn-icon-wrap {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
}
.mfn-badge {
    position: absolute;
    top: -6px;
    right: -8px;
    background: #9dd337;
    color: #fff;
    font-size: 10px;
    font-weight: 700;
    min-width: 16px;
    height: 16px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0 3px;
    line-height: 1;
    border: 1.5px solid #fff;
}
</style>

<script>
// Badge-Sync für mobile Fußzeile
(function() {

    function setMfnCartBadge(count) {
        var badge = document.getElementById('mfnCartBadge');
        if (!badge) return;
        badge.textContent = count;
        badge.style.display = count > 0 ? 'flex' : 'none';
    }

    function setMfnLightboxBadge(count) {
        var badge = document.getElementById('mfnLightboxBadge');
        if (!badge) return;
        badge.textContent = count;
        badge.style.display = count > 0 ? 'flex' : 'none';
    }

    // Cart: dieselbe Quelle wie das sticky Shop-Cart-Icon
    // .speedshot-shop-cart-icon .cart-count wird von media-hub-integration.js gepflegt
    function observeShopCartIcon() {
        var cartIcon = document.querySelector('.speedshot-shop-cart-icon');
        if (cartIcon) {
            function readCount() {
                var el = cartIcon.querySelector('.cart-count');
                setMfnCartBadge(el ? (parseInt(el.textContent) || 0) : 0);
            }
            readCount(); // Initial
            new MutationObserver(readCount).observe(cartIcon, {
                childList: true, subtree: true, characterData: true
            });
        } else {
            setTimeout(observeShopCartIcon, 300);
        }
    }

    // Merkliste: #lightboxBadge beobachten
    function observeLightboxBadge() {
        var src = document.getElementById('lightboxBadge');
        if (src) {
            setMfnLightboxBadge(parseInt(src.textContent) || 0);
            new MutationObserver(function() {
                setMfnLightboxBadge(parseInt(src.textContent) || 0);
            }).observe(src, { childList: true, characterData: true, subtree: true });
        } else {
            setTimeout(observeLightboxBadge, 300);
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        observeShopCartIcon();
        observeLightboxBadge();
    });

})();
</script>
