    <div class="ssf-gm__box">

        
                <div class="ssf-gm__header">
            <h2>Wir suchen Fotografen</h2>
        </div>
        
                <div class="ssf-gm__body">
                        <p>Werde jetzt Fotograf bei Speedshot<br />
<a href="https://speedshot.net/recruiting/fotograf-werden/fotografen-gesucht-v3">Mehr dazu &gt;&gt;&gt;</a></p>
