<style>
/* ===== SSF Global Modal ===== */

/* Base */
.ssf-gm { z-index: 99998; }

/* ── Center Overlay ── */
.ssf-gm--center {
    position: fixed; top: 0; left: 0; width: 100%; height: 100%;
    display: flex; align-items: center; justify-content: center;
}
.ssf-gm--center .ssf-gm__overlay {
    position: absolute; top: 0; left: 0; width: 100%; height: 100%;
    background: rgba(0,0,0,.75); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);
}
.ssf-gm--center .ssf-gm__box {
    position: relative; background: #fff; border-radius: 16px;
    width: 90%; max-height: 85vh;
    display: flex; flex-direction: column; overflow: hidden;
    box-shadow: 0 20px 60px rgba(0,0,0,.4);
    animation: ssfGmSlideIn .4s cubic-bezier(.34,1.56,.64,1);
}

/* ── Corner Notifications ── */
.ssf-gm--top-left,
.ssf-gm--top-right,
.ssf-gm--bottom-left,
.ssf-gm--bottom-right {
    position: fixed;
}
.ssf-gm--top-left    { top: 20px; left: 20px; }
.ssf-gm--top-right   { top: 20px; right: 20px; }
.ssf-gm--bottom-left  { bottom: 20px; left: 20px; }
.ssf-gm--bottom-right { bottom: 20px; right: 20px; }

.ssf-gm--top-left .ssf-gm__box,
.ssf-gm--top-right .ssf-gm__box,
.ssf-gm--bottom-left .ssf-gm__box,
.ssf-gm--bottom-right .ssf-gm__box {
    width: 320px; max-width: calc(100vw - 40px);
    background: #fff; border-radius: 12px;
    box-shadow: 0 8px 32px rgba(0,0,0,.18);
    animation: ssfGmSlideIn .35s cubic-bezier(.34,1.56,.64,1);
    overflow: hidden;
}

/* ── Banners ── */
.ssf-gm--top-banner,
.ssf-gm--bottom-banner {
    position: fixed; left: 0; width: 100%;
}
.ssf-gm--top-banner    { top: 0; }
.ssf-gm--bottom-banner { bottom: 0; }

.ssf-gm--top-banner .ssf-gm__box,
.ssf-gm--bottom-banner .ssf-gm__box {
    width: 100%;
    display: flex; align-items: center; gap: 12px;
    padding: 12px 20px;
    background: #fff; border: none;
    box-shadow: 0 2px 12px rgba(0,0,0,.12);
    flex-wrap: wrap;
}
.ssf-gm--top-banner .ssf-gm__box { border-bottom: 1px solid #e5e7eb; }
.ssf-gm--bottom-banner .ssf-gm__box { border-top: 1px solid #e5e7eb; }

/* ── Close Button ── */
.ssf-gm__close {
    position: absolute; top: 10px; right: 10px;
    width: 32px; height: 32px; border: none;
    background: rgba(0,0,0,.06); border-radius: 50%;
    cursor: pointer; font-size: 16px; color: #666;
    transition: all .2s; display: flex; align-items: center; justify-content: center;
    z-index: 10; line-height: 1;
}
.ssf-gm__close:hover { background: rgba(0,0,0,.12); color: #333; transform: scale(1.1); }

.ssf-gm--top-banner .ssf-gm__close,
.ssf-gm--bottom-banner .ssf-gm__close {
    position: static; margin-left: auto; flex-shrink: 0;
    background: transparent; font-size: 18px; color: #999;
}

/* ── Header ── */
.ssf-gm__header { padding: 22px 24px 0; flex-shrink: 0; }
.ssf-gm__header h2 {
    margin: 0; font-size: 20px; font-weight: 700; color: #1a1a1a;
    line-height: 1.3; padding-right: 36px;
}
.ssf-gm--top-left .ssf-gm__header,
.ssf-gm--top-right .ssf-gm__header,
.ssf-gm--bottom-left .ssf-gm__header,
.ssf-gm--bottom-right .ssf-gm__header { padding: 16px 16px 0; }
.ssf-gm--top-left .ssf-gm__header h2,
.ssf-gm--top-right .ssf-gm__header h2,
.ssf-gm--bottom-left .ssf-gm__header h2,
.ssf-gm--bottom-right .ssf-gm__header h2 { font-size: 16px; }

/* ── Body ── */
.ssf-gm__body {
    padding: 16px 24px; flex: 1; min-height: 0;
    font-size: 14px; line-height: 1.6; color: #444;
    overflow-y: auto; scrollbar-width: thin; scrollbar-color: #ddd transparent;
}
.ssf-gm__body::-webkit-scrollbar { width: 5px; }
.ssf-gm__body::-webkit-scrollbar-thumb { background: #ddd; border-radius: 3px; }
.ssf-gm__body p { margin: 0 0 10px; }
.ssf-gm__body p:last-child { margin-bottom: 0; }
.ssf-gm__body a { color: inherit; text-decoration: underline; text-underline-offset: 2px; }

.ssf-gm--top-left .ssf-gm__body,
.ssf-gm--top-right .ssf-gm__body,
.ssf-gm--bottom-left .ssf-gm__body,
.ssf-gm--bottom-right .ssf-gm__body { padding: 10px 16px; font-size: 13px; }

.ssf-gm--top-banner .ssf-gm__body,
.ssf-gm--bottom-banner .ssf-gm__body {
    padding: 0; flex: 1; overflow: visible; font-size: 14px;
}

/* ── Footer / Buttons ── */
.ssf-gm__footer { padding: 12px 24px 20px; flex-shrink: 0; display: flex; justify-content: center; }
.ssf-gm--top-left .ssf-gm__footer,
.ssf-gm--top-right .ssf-gm__footer,
.ssf-gm--bottom-left .ssf-gm__footer,
.ssf-gm--bottom-right .ssf-gm__footer { padding: 10px 16px 14px; }

.ssf-gm__btn {
    padding: 10px 32px; border: none; border-radius: 8px;
    color: #fff; font-size: 14px; font-weight: 700;
    cursor: pointer; transition: all .2s; letter-spacing: .3px;
}
.ssf-gm__btn:hover { filter: brightness(1.1); transform: translateY(-1px); box-shadow: 0 4px 12px rgba(0,0,0,.15); }
.ssf-gm__btn:active { transform: translateY(0); }

.ssf-gm__banner-btn {
    padding: 8px 20px; border: none; border-radius: 6px;
    color: #fff; font-size: 13px; font-weight: 700;
    cursor: pointer; transition: all .2s; white-space: nowrap; flex-shrink: 0;
}
.ssf-gm__banner-btn:hover { filter: brightness(1.1); }

/* ── Link / CTA ── */
.ssf-gm__footer { gap: 10px; flex-wrap: wrap; align-items: center; }
.ssf-gm__link {
    display: inline-block; padding: 10px 24px; border: 2px solid currentColor;
    border-radius: 8px; font-size: 14px; font-weight: 700; text-decoration: none;
    transition: all .2s; letter-spacing: .3px;
}
.ssf-gm__link:hover { opacity: .8; transform: translateY(-1px); }
.ssf-gm__banner-link {
    font-size: 13px; font-weight: 700; text-decoration: underline; white-space: nowrap; flex-shrink: 0;
}
.ssf-gm__banner-link:hover { opacity: .75; }

/* ── Animations ── */
@keyframes ssfGmSlideIn {
    from { opacity: 0; transform: translateY(-20px) scale(.96); }
    to   { opacity: 1; transform: translateY(0) scale(1); }
}
.ssf-gm--bottom-left .ssf-gm__box,
.ssf-gm--bottom-right .ssf-gm__box {
    animation-name: ssfGmSlideInUp;
}
@keyframes ssfGmSlideInUp {
    from { opacity: 0; transform: translateY(20px) scale(.96); }
    to   { opacity: 1; transform: translateY(0) scale(1); }
}
.ssf-gm--top-banner .ssf-gm__box { animation-name: ssfGmSlideDown; }
@keyframes ssfGmSlideDown {
    from { opacity: 0; transform: translateY(-100%); }
    to   { opacity: 1; transform: translateY(0); }
}
.ssf-gm--bottom-banner .ssf-gm__box { animation-name: ssfGmSlideUp; }
@keyframes ssfGmSlideUp {
    from { opacity: 0; transform: translateY(100%); }
    to   { opacity: 1; transform: translateY(0); }
}

/* Closing */
.ssf-gm.ssf-gm--closing { animation: ssfGmFadeOut .25s ease-out forwards; }
@keyframes ssfGmFadeOut { from { opacity:1; } to { opacity:0; } }
.ssf-gm--closing .ssf-gm__box { transition: transform .25s ease-out, opacity .25s ease-out; opacity: 0; }

/* Responsive */
@media (max-width: 640px) {
    .ssf-gm--top-left .ssf-gm__box,
    .ssf-gm--top-right .ssf-gm__box,
    .ssf-gm--bottom-left .ssf-gm__box,
    .ssf-gm--bottom-right .ssf-gm__box {
        width: calc(100vw - 24px); max-width: none;
    }
    .ssf-gm--top-left, .ssf-gm--top-right { top: 12px; left: 12px; right: 12px; }
    .ssf-gm--bottom-left, .ssf-gm--bottom-right { bottom: 12px; left: 12px; right: 12px; }
    .ssf-gm--center .ssf-gm__box { width: 95%; max-height: 90vh; }
}
</style>

<script>
(function() {
    'use strict';

    var modal = document.getElementById('ssfGlobalModal');
    if (!modal) return;

    var modalId     = modal.dataset.modalId;
    var displayMode = modal.dataset.displayMode;
    var cookieDays  = parseInt(modal.dataset.cookieDays) || 30;
    var delayMs     = parseInt(modal.dataset.delayMs) || 0;
    var cookieName  = modal.dataset.cookieName;
    var sessionKey  = 'ssf_gm_s_' + modalId;

    function getCookie(name) {
        var match = document.cookie.match(new RegExp('(^| )' + name + '=([^;]+)'));
        return match ? match[2] : null;
    }

    function setCookie(name, value, days) {
        var date = new Date();
        date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
        document.cookie = name + '=' + value + ';expires=' + date.toUTCString() + ';path=/;SameSite=Lax';
    }

    function shouldShow() {
        switch (displayMode) {
            case 'first_visit':
                return !getCookie(cookieName);
            case 'once_per_session':
                try { return !sessionStorage.getItem(sessionKey); }
                catch(e) { return !getCookie(cookieName + '_s'); }
            case 'always':
                return true;
            default:
                return false;
        }
    }

    function markAsSeen() {
        switch (displayMode) {
            case 'first_visit':
                setCookie(cookieName, '1', cookieDays);
                break;
            case 'once_per_session':
                try { sessionStorage.setItem(sessionKey, '1'); }
                catch(e) { setCookie(cookieName + '_s', '1', 1); }
                break;
        }
    }

    function openModal() {
        modal.style.display = '';  /* restores the element as block/flex via CSS */
        /* Center overlays need body scroll lock */
        if (modal.classList.contains('ssf-gm--center')) {
            document.body.style.overflow = 'hidden';
        }
        var firstFocus = modal.querySelector('.ssf-gm__btn, .ssf-gm__close, .ssf-gm__banner-btn');
        if (firstFocus) firstFocus.focus();
    }

    window.ssfGmClose = function() {
        markAsSeen();
        modal.classList.add('ssf-gm--closing');
        setTimeout(function() {
            modal.style.display = 'none';
            modal.classList.remove('ssf-gm--closing');
            if (modal.classList.contains('ssf-gm--center')) {
                document.body.style.overflow = '';
            }
        }, 260);
    };

    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && modal.style.display !== 'none') {
            ssfGmClose();
        }
    });

    if (shouldShow()) {
        if (delayMs > 0) {
            setTimeout(openModal, delayMs);
        } else {
            requestAnimationFrame(function() { requestAnimationFrame(openModal); });
        }
    }
})();
</script>
        </body>
</html>
